                    , NULL AS bin_id
                    , isnull(
                         CASE CHARINDEX('^', a.SITE_ID)
                            WHEN 0 THEN a.SITE_ID
       ELSE substring(a.SITE_ID, 1, CHARINDEX('^', a.SITE_ID) - 1)
