                    , a.OPERATION_QTY AS plan_in_qty
                    , b.order_type
                    , b.production_type
                    , case when d.po_type = 'REPLAN' then 'F' else '' end as fix_type
              FROM 
                      dbo.TH_BUF_SCM_WORK_ORDER  AS a
                      LEFT OUTER JOIN TH_BUF_SCM_PRODUCTION_A  AS c
                        ON a.WORK_ORDER_ID = c.WORK_ORDER_ID AND a.RESOURCE_ID = c.resource_id 
                      LEFT OUTER JOIN TH_BUF_SCM_PRODUCTION_B  AS d
