              AND a.PLAN_ID = b.PLAN_ID 
              AND a.WORK_ORDER_ID = b.ORDER_ID
            LEFT OUTER JOIN dbo.TH_BUF_SCM_PRODUCTION_B  AS C
              ON  B.PLAN_ORDER_ID = C.WORK_ORDER_ID
      
      --LOG 생성
      SET @v_message = @@ROWCOUNT
      SET @v_table_name = 'TH_BUF_SCM_PRODUCTION_D'
      SET @n_log_count = @n_log_count + 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null



      /*** ## ProductionPlanDetail..!! ***/

      DELETE FROM TH_BUF_SCM_PRODUCTION

      INSERT INTO TH_BUF_SCM_PRODUCTION
            (
              INSTANCE_ID
            , FP_PLAN_ID
            , COMPANY_ID
            , DIVISION_ID
            , SITE_ID
            , PLANT_ID
            , FACTORY_ID
            , WORK_ORDER_SPL_ID
            , WORK_ORDER_ID
            , BATCH_ORDER_ID
            , BIN_ORDER_ID
            , SCP_TARGET_ID
            , DEMAND_ID
            , ITEM_ID
            , TOP_ITEM_ID
            , LINE_ID
            , OPERATION_ID
            , WORK_CENTER_ID
            , ELECTRODE_TYPE
            , EQUIPMENT_ID
            , PLAN_DATE
            , START_TIME
            , END_TIME
            , PLAN_QTY
            , PLAN_IN_QTY
            , FIX_TYPE
            , ORDER_TYPE
            , PRODUCTION_TYPE
            )            
      SELECT 
                A.MASTER_ID
              , A.PLAN_ID
              , B.IRS_ATTB_11   AS COMPANY_ID
              , B.IRS_ATTB_12   AS DIVISION_ID
              , B.IRS_ATTB_13   AS SITE_ID
              , B.IRS_ATTB_14   AS PLANT_ID
              , A.SITE_ID       AS FACTORY_ID
              , A.WORK_ORDER_ID AS WORK_ORDER_SPL_ID
              , A.WORK_ORDER_ID
              --, PRODUCTION_ORDER_ID
              , '-'             AS BATCH_ORDER_ID
              , '-'             AS BIN_ORDER_ID
              , A.ORG_DEMAND_ID
              , A.DEMAND_ID
              , A.ITEM_ID
              , A.TOP_ITEM_ID
              , A.ROUTE_ID AS LINE_ID
              , A.OPERATION_ID AS OPERATION_ID
              , ISNULL(C.RES_ATTB_19, '-') AS WORK_CENTER_ID
              , ISNULL(C.RES_ATTB_20, '-') AS ELECTRODE_TYPE
              , A.RESOURCE_ID
              , A.PLAN_DATE
              , MIN(A.START_TIME) AS START_TIME
              , MAX(A.END_TIME) AS END_TIME
              , SUM(A.PLAN_QTY) AS PLAN_QTY
              , SUM(A.PLAN_IN_QTY) AS PLAN_IN_QTY
              , A.FIX_TYPE
              , A.ORDER_TYPE
              , A.PRODUCTION_TYPE
      FROM   TH_BUF_SCM_PRODUCTION_D  A,
             TH_MST_ITEM_ROUTE_SITE   B,
             TH_MST_RESOURCE          C
      WHERE  A.MASTER_ID = B.MASTER_ID
      AND    A.PLAN_ID = B.PLAN_ID
      AND    A.ITEM_ID = B.ITEM_ID
      AND    A.SITE_ID = B.SITE_ID
      AND    A.ROUTE_ID = B.ROUTE_ID
      AND    A.OPERATION_ID = B.OPERATION_ID
      AND    A.MASTER_ID = C.MASTER_ID
      AND    A.PLAN_ID = C.PLAN_ID
      AND    A.RESOURCE_ID = C.RESOURCE_ID
      GROUP  BY
                A.MASTER_ID
              , A.PLAN_ID
              , B.IRS_ATTB_11
              , B.IRS_ATTB_12
              , B.IRS_ATTB_13
              , B.IRS_ATTB_14
              , A.SITE_ID
              , A.WORK_ORDER_ID
              , A.PRODUCTION_ORDER_ID
              , A.ORG_DEMAND_ID
              , A.DEMAND_ID
              , A.ITEM_ID
              , A.TOP_ITEM_ID
              , A.BIN_ID
              , A.SITE_ID
              , A.ROUTE_ID
              , A.OPERATION_ID
              , ISNULL(C.RES_ATTB_19, '-')
              , ISNULL(C.RES_ATTB_20, '-')
              , A.RESOURCE_ID
              , A.SUB_RESOURCE_ID
              , A.PLAN_DATE
              , A.ORDER_TYPE
              , A.PRODUCTION_TYPE
              , A.FIX_TYPE

      SET @n_cnt2 = @n_cnt2 + @@ROWCOUNT
      
      --LOG 생성
      SET @v_message = 'PLAN ORDER : ' + convert(nvarchar, @n_cnt2)
      SET @n_log_count += 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PRODUCTION', 'INSERT', @n_log_count, null, @v_message, null 

      ----------------------------------------------------------------------------------------------------
