      ----------------------------------------------------------------------------------------------------

      SET @v_table_name = 'TH_BUF_SCM_PRODUCTION'
      
      UPDATE TH_BUF_SCM_PRODUCTION
      SET    TH_BUF_SCM_PRODUCTION.PRODUCTION_TYPE = B.PRODUCTION_TYPE
      FROM   TH_BUF_SCM_PRODUCTION A,
             (
              SELECT WORK_ORDER_ID, 
                     MAX(ISNULL(PRODUCTION_TYPE,'MAS')) AS PRODUCTION_TYPE
              FROM   TH_MST_SCM_ORDER_STATUS
              WHERE  INSTANCE_ID = @v_master_id
              AND    FP_PLAN_ID = @v_plan_id
              GROUP BY WORK_ORDER_ID
             ) B
      WHERE  A.INSTANCE_ID = @v_master_id
      AND    A.FP_PLAN_ID = @v_plan_id
      AND    A.WORK_ORDER_ID = B.WORK_ORDER_ID

      -- FIX BATCH ORDER ID 채번 : 순서 바꾸지 말것...
      UPDATE TH_BUF_SCM_PRODUCTION
      SET    TH_BUF_SCM_PRODUCTION.BATCH_ORDER_ID = B.BATCH_ORDER_ID
      FROM   TH_BUF_SCM_PRODUCTION A,
             TH_MST_SCM_ORDER_STATUS B
      WHERE  A.INSTANCE_ID = @v_master_id
      AND    A.FP_PLAN_ID = @v_plan_id
      AND    A.INSTANCE_ID = B.INSTANCE_ID
      AND    A.FP_PLAN_ID = B.FP_PLAN_ID
      AND    A.WORK_ORDER_SPL_ID = B.WORK_ORDER_ID
      AND    ISNULL(B.BATCH_ORDER_ID, '-') != '-'

      --LOG 생성
      SET @v_message = 'FIX BATCH_ORDER_ID UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
      SET @n_log_count = @n_log_count + 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null


      -- NORMAL BATCH ORDER ID 채번 : 순서 바꾸지 말것...
      UPDATE TH_BUF_SCM_PRODUCTION
      SET    TH_BUF_SCM_PRODUCTION.BATCH_ORDER_ID =B.BATCH_GROUP_ORDER_ID
      FROM   TH_BUF_SCM_PRODUCTION A,
             (
              SELECT A.*, B.BATCH_GROUP_ID
                    ,DENSE_RANK() OVER (PARTITION BY  A.INSTANCE_ID
                                                    , A.FP_PLAN_ID
                                        ORDER     BY  A.EQUIPMENT_ID
                                                    , B.BATCH_GROUP_ID
                                                    , A.START_TIME
                                                    , A.END_TIME) GROUP_SEQ
                    ,MIN(WORK_ORDER_ID) OVER (PARTITION BY  A.INSTANCE_ID
                                                          , A.FP_PLAN_ID
                                                          , A.EQUIPMENT_ID
                                                          , B.BATCH_GROUP_ID
                                                          , A.START_TIME
                                                          , A.END_TIME) BATCH_GROUP_ORDER_ID
              FROM   TH_BUF_SCM_PRODUCTION A,
                     (
                      SELECT DISTINCT
                             A.MASTER_ID, A.PLAN_ID, A.BATCH_GROUP_ID,
                             CASE WHEN CHARINDEX('_BATCH',A.ITEM_ID) = 0 THEN A.ITEM_ID
                                  ELSE SUBSTRING(A.ITEM_ID, 1, CHARINDEX('_BATCH',A.ITEM_ID) - 1 ) 
                             END  AS ITEM_ID,
                             B. RESOURCE_ID
                      FROM   TH_ENG_BATCH_INFO  a,
                             TH_ENG_RESOURCE    B
                      where  A.MASTER_ID = @v_master_id
                      AND    A.PLAN_ID = @v_plan_id
                      AND    A.PLAN_ID = B.PLAN_ID
                      AND    A.BATCH_RES_GROUP_ID = B.BATCH_RES_GROUP_ID
                      AND    B.BATCH_TYPE = 'BATCH'
                     ) B
              WHERE  A.INSTANCE_ID = B.MASTER_ID
              AND    A.FP_PLAN_ID = B.PLAN_ID
              AND    A.EQUIPMENT_ID = B.RESOURCE_ID
              AND    A.ITEM_ID = B.ITEM_ID
              AND    ISNULL(A.BATCH_ORDER_ID, '-') = '-'    -- ## BATCH ORDER ID 가 할당되지 않는 경우에만 묶는다.
             ) B
      WHERE  A.INSTANCE_ID = @v_master_id
      AND    A.FP_PLAN_ID = @v_plan_id
      --AND    A.WORK_ORDER_ID = B.WORK_ORDER_ID
      AND    A.WORK_ORDER_SPL_ID = B.WORK_ORDER_SPL_ID

      --LOG 생성
      SET @v_message = 'BATCH_ORDER_ID UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
      SET @n_log_count = @n_log_count + 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

      UPDATE TH_BUF_SCM_PRODUCTION
      SET    TH_BUF_SCM_PRODUCTION.LANE_QTY      = ISNULL(C.MAIN_LANE_QTY, C.LANE_QTY)    -- HS 에서 짜를 QTY
            ,TH_BUF_SCM_PRODUCTION.LANE_TACT_QTY = ISNULL(C.LANE_QTY, 0)                  -- 실제 계획에 반영된 QTY
      FROM   TH_BUF_SCM_PRODUCTION A,
             TH_EXP_PLANORDER B,
             TH_EXP_LANEORDER C
      WHERE  A.INSTANCE_ID = @v_master_id
      AND    A.FP_PLAN_ID = @v_plan_id
      AND    A.INSTANCE_ID = B.MASTER_ID
      AND    A.FP_PLAN_ID = B.PLAN_ID
      AND    A.WORK_ORDER_ID = B.PLAN_ORDER_ID
      AND    B.MASTER_ID = C.MASTER_ID
      AND    B.PLAN_ID = C.PLAN_ID
      AND    B.ORDER_ID = C.ORDER_ID 

      --LOG 생성
      SET @v_message = 'MAIN_LANE_QTY UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
      SET @n_log_count = @n_log_count + 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

      UPDATE TH_BUF_SCM_PRODUCTION
      SET    TH_BUF_SCM_PRODUCTION.LANE_QTY      = ISNULL(C.SUB_LANE_QTY,0)
            ,TH_BUF_SCM_PRODUCTION.LANE_TACT_QTY = ISNULL(C.LANE_QTY, 0)                  -- 실제 계획에 반영된 QTY
      FROM   TH_BUF_SCM_PRODUCTION A,
             TH_EXP_PLANORDER B,
             TH_EXP_LANEORDER C
      WHERE  A.INSTANCE_ID = @v_master_id
      AND    A.FP_PLAN_ID = @v_plan_id
      AND    A.INSTANCE_ID = B.MASTER_ID
      AND    A.FP_PLAN_ID = B.PLAN_ID
      AND    A.WORK_ORDER_ID = B.PLAN_ORDER_ID
      AND    B.MASTER_ID = C.MASTER_ID
      AND    B.PLAN_ID = C.PLAN_ID
      AND    B.ORDER_ID = C.SUB_ORDER_ID 

      --LOG 생성
      SET @v_message = 'SUB MAIN_LANE_QTY UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
      SET @n_log_count = @n_log_count + 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

      UPDATE TH_BUF_SCM_PRODUCTION
      SET    TH_BUF_SCM_PRODUCTION.BIN_ORDER_ID = B.BIN_WORK_ORDER_ID
      FROM   TH_BUF_SCM_PRODUCTION A,
             (
              SELECT A.MASTER_ID, A.PLAN_ID, A.ORDER_ID, A.BIN_ORDER_ID,
                     B.PLAN_ORDER_ID AS WORK_ORDER_ID,
                     C.PLAN_ORDER_ID AS BIN_WORK_ORDER_ID
              FROM   (
                      SELECT A.MASTER_ID, A.PLAN_ID,
                             CASE WHEN INT = 1 THEN ORDER_ID
                                               ELSE SUB_ORDER_ID
                             END  ORDER_ID,
                             ORDER_ID AS BIN_ORDER_ID
                      FROM   TH_EXP_LANEORDER A,
                             COPYT            B
                      WHERE  A.MASTER_ID = @v_master_id
                      AND    A.PLAN_ID = @v_plan_id
                      AND    A.SUB_ORDER_ID IS NOT NULL
                      AND    B.INT <= 2       
                     ) A,
                     TH_EXP_PLANORDER B,
                     TH_EXP_PLANORDER C
              WHERE  A.MASTER_ID = B.MASTER_ID
              AND    A.PLAN_ID = B.PLAN_ID
              AND    A.ORDER_ID = B.ORDER_ID
              AND    A.MASTER_ID = C.MASTER_ID
              AND    A.PLAN_ID = C.PLAN_ID
              AND    A.BIN_ORDER_ID = C.ORDER_ID
             ) B
      WHERE  A.INSTANCE_ID = @v_master_id
      AND    A.FP_PLAN_ID = @v_plan_id
      AND    A.INSTANCE_ID = B.MASTER_ID
      AND    A.FP_PLAN_ID = B.PLAN_ID
      AND    A.WORK_ORDER_ID = B.WORK_ORDER_ID

      --LOG 생성
      SET @v_message = 'BIN_ORDER_ID UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
      SET @n_log_count = @n_log_count + 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

      UPDATE TH_BUF_SCM_PRODUCTION
      SET    TH_BUF_SCM_PRODUCTION.TOP_WORK_ORDER_ID = B.TOP_WORK_ORDER_ID
      FROM   TH_BUF_SCM_PRODUCTION A
             INNER JOIN 
                             (
                              SELECT A.DEMAND_ID, C.PLAN_ORDER_ID AS TOP_WORK_ORDER_ID
                              FROM   TH_BUF_OUT_ITEM_PEGGING  A,
                                     TH_BUF_OUT_ITEM_PEGGING  B,
                                     TH_EXP_PLANORDER     C
                              WHERE  A.MASTER_ID = @v_master_id
                              AND    A.PLAN_ID = @v_plan_id
                              AND    A.OUT_VERSION_ID = @v_out_version_id
                              AND    A.DEMAND_ID IS NOT NULL
                              AND    A.MASTER_ID = B.MASTER_ID
                              AND    A.PLAN_ID = B.PLAN_ID
                              AND    A.OUT_VERSION_ID = B.OUT_VERSION_ID
                              AND    A.IN_ITEM_PEGGING_ID = B.OUT_ITEM_PEGGING_ID
                              AND    A.MASTER_ID = C.MASTER_ID
                              AND    A.PLAN_ID = C.PLAN_ID
                              AND    B.WORK_ORDER_ID = C.ORDER_ID
                             ) B
                     ON A.DEMAND_ID = B.DEMAND_ID
      WHERE  A.INSTANCE_ID = @v_master_id
      AND    A.FP_PLAN_ID = @v_plan_id

      --LOG 생성
      SET @v_message = 'TOP_WORK_ORDER_ID UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
      SET @n_log_count = @n_log_count + 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null



/*
---------------------------------------------------------------------------------------------------------
-- LINE 계획일 경우 설비 수 만큼 N 빵하는 로직 주석처리함.
---------------------------------------------------------------------------------------------------------

      IF @res_category = 'LINE'
        BEGIN
          
          DELETE FROM TH_EXP_PRODUCTION_PLAN
          WHERE  INSTANCE_ID = @v_master_id
