          EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN', 'DELETE', @n_log_count, null, @v_message, null 

          INSERT INTO TH_EXP_PRODUCTION_PLAN
                (
                  INSTANCE_ID
                , FP_PLAN_ID
                , COMPANY_ID
                , DIVISION_ID
                , SITE_ID
                , PLANT_ID
                , FACTORY_ID
                --, WORK_ORDER_SPL_ID
                , WORK_ORDER_ID
                , BATCH_ORDER_ID
                , BIN_ORDER_ID
                , ORDER_TYPE
                , SCP_TARGET_ID
                , DEMAND_ID
                , ITEM_ID
                , LANE_QTY
                , TOP_ITEM_ID
                , LINE_ID
                , OPERATION_ID
                , ELECTRODE_TYPE
                , WORK_CENTER_ID
                --, EQUIPMENT_ID
                , PLAN_DATE
                , START_TIME
                , END_TIME
                , PLAN_QTY
                , PLAN_IN_QTY
                , FIX_TYPE
                , PRODUCTION_TYPE
                , LANE_TACT_QTY
                , INSERT_ID
                , INSERT_TIME
                )
          SELECT       
                  A.INSTANCE_ID
                , A.FP_PLAN_ID
                , A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , A.FACTORY_ID
                --, A.WORK_ORDER_SPL_ID
                , A.WORK_ORDER_ID
                , A.BATCH_ORDER_ID
                , A.BIN_ORDER_ID
                , A.ORDER_TYPE
                , A.SCP_TARGET_ID
                , A.DEMAND_ID
                , A.ITEM_ID
                , A.LANE_QTY
                , A.TOP_ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , A.ELECTRODE_TYPE
                , A.WORK_CENTER_ID
                --, A.EQUIPMENT_ID
                , A.PLAN_DATE
                , A.START_TIME
                , A.END_TIME
                , A.PLAN_QTY
                , A.PLAN_IN_QTY
                , A.FIX_TYPE
                , A.PRODUCTION_TYPE
                , A.LANE_TACT_QTY
                , @v_proc_name    AS INSERT_ID
                , GETDATE()       AS INSERT_TIME
          FROM    TH_BUF_SCM_PRODUCTION A
          WHERE   A.INSTANCE_ID = @v_master_id
          AND     A.FP_PLAN_ID = @v_plan_id
          AND     A.FACTORY_ID != 'VIRTUAL_LANE'

          SET @v_message = @@ROWCOUNT
          SET @n_log_count += 1
          EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN', 'INSERT', @n_log_count, null, @v_message, null 



          DELETE FROM TH_EXP_PRODUCTION_PLAN_EQUIPMENT
          WHERE  INSTANCE_ID  = @v_master_id
          AND    FP_PLAN_ID   = @v_plan_id

          /*
          -- REPLAN 계획일 경우 이미 설비, 수량이 고정되어 있으므로 시간만 변경
          INSERT INTO TH_EXP_PRODUCTION_PLAN_EQUIPMENT
    (
                       INSTANCE_ID        
                      ,FP_PLAN_ID       
                      ,COMPANY_ID       
                      ,DIVISION_ID      
                      ,SITE_ID          
                      ,PLANT_ID         
                      ,FACTORY_ID       
                      ,WORK_ORDER_SPL_ID
                      ,WORK_ORDER_ID  
                      ,BATCH_ORDER_ID
                      ,BIN_ORDER_ID
                      ,ORDER_TYPE
                      ,SCP_TARGET_ID    
                      ,DEMAND_ID        
                      ,ITEM_ID  
                      ,LANE_QTY
                      ,TOP_ITEM_ID      
                      ,TOP_WORK_ORDER_ID
                      ,LINE_ID          
                      ,OPERATION_ID     
                      ,ELECTRODE_TYPE
                      ,WORK_CENTER_ID   
                      ,EQUIPMENT_ID     
                      ,PLAN_DATE        
                      ,START_TIME       
                      ,END_TIME         
                      ,PLAN_QTY         
                      ,PLAN_IN_QTY      
                      ,FIX_TYPE         
                      ,PRODUCTION_TYPE  
                      ,BOM_VERSION_ID   
                      ,INSERT_ID        
                      ,INSERT_TIME   
                    )
          SELECT  A.MASTER_ID
                , A.PLAN_ID
                , C.IRS_ATTB_11 AS COMPANY_ID
                , C.IRS_ATTB_12 AS DIVISION_ID
                , C.IRS_ATTB_13 AS SITE_ID
                , C.IRS_ATTB_14 AS PLANT_ID
                , A.SITE_ID     AS FACTORY_ID
                , A.WORK_ORDER_SPL_ID
                , A.WORK_ORDER_ID
                , '' BATCH_ORDER_ID
                , '' BIN_ORDER_ID
                , A.ORDER_TYPE
                , A.SCP_TARGET_ID
                , A.DEMAND_ID
                , A.ITEM_ID
                , NULL LANE_QTY
                , A.TOP_ITEM_ID
                , A.TOP_WORK_ORDER_ID
                , A.ROUTE_ID AS LINE_ID
                , A.OPERATION_ID
                , B.RES_ATTB_20 AS ELECTRODE_TYPE
                , B.RES_ATTB_19 AS WORK_CENTER_ID
                , A.EQUIPMENT_ID
                , CONVERT(datetime2, dbo.fn_set_work_date2(a.master_id, a.plan_id, a.start_time, a.end_time), 112) AS plan_date
                , A.START_TIME
                , A.END_TIME
                , A.PLAN_QTY
                , (PLAN_QTY / COMPLETE_QTY) * OPERATION_QTY PLAN_IN_QTY
                , A.FIX_TYPE
                , A.PRODUCTION_TYPE
                , NULL BOM_VERSION_ID
                , @v_proc_name    AS INSERT_ID
                , GETDATE()       AS INSERT_TIME
          from   (
                  SELECT A.MASTER_ID, 
                         A.PLAN_ID,
                         A.SITE_ID, 
                         A.WORK_ORDER_ID AS WORK_ORDER_SPL_ID,
                         A.WORK_ORDER_ID,
                         --B.WORK_ORDER_SPL_ID,
                         --B.WORK_ORDER_ID,
                         B.ORDER_TYPE,
                         D.DEMAND_ID AS SCP_TARGET_ID,
                         A.DEMAND_ID,
                         A.ITEM_ID,
                         D.SALES_MODEL AS TOP_ITEM_ID,
                         A.TOP_WORK_ORDER_ID,
                         A.ROUTE_ID,
                         A.OPERATION_ID,
                         B.EQUIPMENT_ID,
                         C.START_TIME,
                         C.END_TIME,
                         C.OPERATION_QTY,
                         C.COMPLETE_QTY,
                         B.PLAN_QTY AS PLAN_QTY,
                         B.PLAN_QTY AS PLAN_IN_QTY,
                         'F' AS FIX_TYPE,
                         D.ORDER_TYPE AS PRODUCTION_TYPE
                  FROM   (
                          SELECT  A.MASTER_ID
                                , A.PLAN_ID
        , B.WORK_ORDER_ID as WORK_ORDER_ID        -- SOFT PEGGING SPLIT
                                , A.WORK_ORDER_ID AS REPLAN_ORDER_ID      -- ORG FIX WORK ORDER
                                , a.ITEM_ID
                                , a.SITE_ID
                                , a.ROUTE_ID
                                , a.OPERATION_ID
                                , a.PO_TYPE
                                , B.DEMAND_ID
                                , A.TOP_WORK_ORDER_ID
                          FROM    TH_MST_FIXED_PLAN  AS A,
                                  TH_ENG_FIXED_PLAN  AS B
                          WHERE   a.MASTER_ID = @v_master_id 
                          AND     a.PLAN_ID = @v_plan_id
                          AND     A.MASTER_ID = B.MASTER_ID
                          AND     A.PLAN_ID = B.PLAN_ID
                          AND     A.WORK_ORDER_ID = ISNULL(B.DESCR, B.WORK_ORDER_ID)                  
                         ) A, 
                         TH_MST_SCM_ORDER_STATUS  B,
                         TH_BUF_OUT_WORK_ORDER        C,
                         TH_DPP_NET_DEMAND        D
                  WHERE  A.MASTER_ID = @v_master_id
                  AND    A.PLAN_ID = @v_plan_id
                  AND    A.PO_TYPE = 'REPLAN'
                  AND    A.MASTER_ID = B.INSTANCE_ID
                  AND    A.PLAN_ID   = B.FP_PLAN_ID
                  AND    A.REPLAN_ORDER_ID = B.WORK_ORDER_ID
                  AND    A.MASTER_ID = C.MASTER_ID
                  AND    A.PLAN_ID = C.PLAN_ID
                  AND    C.OUT_VERSION_ID = @v_out_version_id
                  AND    A.WORK_ORDER_ID = C.WORK_ORDER_ID
                  AND    A.MASTER_ID = D.MASTER_ID
                  AND    A.PLAN_ID = D.PLAN_ID
                  AND    A.DEMAND_ID = D.NET_DEMAND_ID
                 ) a,
                 TH_MST_RESOURCE        B,
                 TH_MST_ITEM_ROUTE_SITE C
          WHERE  A.MASTER_ID = B.MASTER_ID
          AND    A.PLAN_ID = B.PLAN_ID
          and    A.EQUIPMENT_ID = B.RESOURCE_ID
          AND    A.MASTER_ID = C.MASTER_ID
          AND    A.PLAN_ID = C.PLAN_ID
          AND    A.ITEM_ID = C.ITEM_ID
          AND    A.SITE_ID = C.SITE_ID
          AND    A.ROUTE_ID = C.ROUTE_ID
          AND    A.OPERATION_ID = C.OPERATION_ID
          */
          
          -- REPLAN 이외의 계획에 대해선 설비기준 OFF 감안한 수량을 선별해야 함.
          BEGIN          
          
            -- 라인에 포함된 설비 중 일부 설비에 OFF 된 것만 추출
            -- 라인전체 OFF 일 경우 이미 계획 수립시 반영되어 있으니깐..
            DELETE FROM TH_BUF_SCM_PRODUCTION_OFF

            INSERT INTO TH_BUF_SCM_PRODUCTION_OFF
            SELECT LINE_ID, OPERATION_ID, ELECTRODE_TYPE, RESOURCE_GROUP_ID, START_DATE, END_DATE
            FROM   TH_MST_OFF_CALENDAR_EQUIP A
            WHERE  A.MASTER_ID = @v_master_id
            AND    A.PLAN_ID = @v_plan_id
            AND    NOT EXISTS  (
                                SELECT 1
                                FROM   TH_MST_OFF_CALENDAR_LINE X
                                WHERE  X.MASTER_ID = @v_master_id
                                AND    X.PLAN_ID = @v_plan_id
                                AND    X.LINE_ID = A.LINE_ID
                                AND    X.OPERATION_ID = A.OPERATION_ID
                                AND    X.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND    X.START_DATE = A.START_DATE
                                AND    X.END_DATE = A.END_DATE
                               )

            --LOG 생성
            SET @v_message = @@ROWCOUNT
            SET @n_log_count += 1
            EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PRODUCTION_OFF', 'INSERT', @n_log_count, null, @v_message, null 

            -- 설비별 OFF 를 감안한 실 시간 계산
            DELETE FROM TH_BUF_SCM_PRODUCTION_OFF_RUN
            
            INSERT INTO TH_BUF_SCM_PRODUCTION_OFF_RUN
       SELECT A.WORK_ORDER_ID, A.EQUIPMENT_ID, A.START_TIME, A.END_TIME, A.RUN_TIME AS RUN_SECOND,
                   MAX(RUN_START_TIME) AS RUN_START_TIME,
                   MIN(RUN_END_TIME)   AS RUN_END_TIME,
                   SUM(OFF_TIME)       AS OFF_SECOND
            FROM   (
                    SELECT A.*
                         , DATEDIFF(SS, START_TIME,    END_TIME)    AS RUN_TIME
                         , DATEDIFF(SS, RUN_OFF_START, RUN_OFF_END) AS OFF_TIME
                    FROM   (
                            SELECT  A.WORK_ORDER_ID, C.EQUIPMENT_ID, A.START_TIME, A.END_TIME, C.OFF_START_TIME, C.OFF_END_TIME
                                  , CASE WHEN START_TIME < OFF_START_TIME THEN OFF_START_TIME ELSE START_TIME END RUN_OFF_START
                                  , CASE WHEN END_TIME   > OFF_END_TIME   THEN OFF_END_TIME   ELSE END_TIME   END RUN_OFF_END
                                  , CASE WHEN START_TIME > OFF_START_TIME AND START_TIME < OFF_END_TIME THEN OFF_END_TIME
                                         WHEN START_TIME < OFF_START_TIME                               THEN START_TIME
                                         ELSE NULL
                                    END  RUN_START_TIME   -- GROUP BY MAX 
                                  , CASE WHEN END_TIME   > OFF_START_TIME AND END_TIME   < OFF_END_TIME THEN OFF_START_TIME
                                         WHEN END_TIME   > OFF_END_TIME                                 THEN END_TIME
                                         ELSE NULL
                                    END  RUN_END_TIME     -- GROUP BY MIN
                            FROM    TH_BUF_SCM_PRODUCTION     A,
                                    TH_MST_RESOURCE           B,
                                    TH_BUF_SCM_PRODUCTION_OFF C
                            WHERE   A.FACTORY_ID != 'VIRTUAL_LANE'
                            AND     B.MASTER_ID = @v_master_id
                            AND     B.PLAN_ID = @v_plan_id
                            AND     A.INSTANCE_ID = @v_master_id
                            AND     A.FP_PLAN_ID = @v_plan_id
                            AND     A.EQUIPMENT_ID = B.RESOURCE_ID
                            AND     B.RES_ATTB_17 = C.LINE_ID
                            AND     B.RES_ATTB_18 = C.OPERATION_ID
                            AND     B.RES_ATTB_20 = C.ELECTRODE_TYPE
                            AND     A.START_TIME <= C.OFF_END_TIME
                            AND     A.END_TIME >= C.OFF_START_TIME
                            /*
                            AND     NOT EXISTS (  SELECT 1
                                                  FROM   (
                                                          SELECT 
                                                                  B.WORK_ORDER_ID as WORK_ORDER_ID
                                                                , a.PO_TYPE
                                                          FROM    TH_MST_FIXED_PLAN  AS A,
                                                                  TH_ENG_FIXED_PLAN  AS B
                                                          WHERE   a.MASTER_ID = @v_master_id 
                                                          AND     a.PLAN_ID = @v_plan_id
                                                          AND     A.MASTER_ID = B.MASTER_ID
                                                          AND     A.PLAN_ID = B.PLAN_ID
                                                          AND     A.WORK_ORDER_ID = ISNULL(B.DESCR, B.WORK_ORDER_ID)                                                  
                                                         ) X
                                                  WHERE  X.PO_TYPE = 'REPLAN'
                                                  AND    X.WORK_ORDER_ID = A.WORK_ORDER_ID )
                            */
                           ) A
                   ) A
            GROUP  BY A.WORK_ORDER_ID, A.EQUIPMENT_ID, A.START_TIME, A.END_TIME, A.RUN_TIME
            
            --LOG 생성
            SET @v_message = @@ROWCOUNT
            SET @n_log_count += 1
            EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PRODUCTION_OFF_RUN', 'INSERT', @n_log_count, null, @v_message, null 

            ------------------------------
            
            INSERT INTO TH_EXP_PRODUCTION_PLAN_EQUIPMENT
                      (
                         INSTANCE_ID        
                        ,FP_PLAN_ID       
                        ,COMPANY_ID       
                        ,DIVISION_ID      
                        ,SITE_ID          
                        ,PLANT_ID         
                        ,FACTORY_ID       
                        ,WORK_ORDER_SPL_ID
                        ,WORK_ORDER_ID  
                        ,BATCH_ORDER_ID
                        ,BIN_ORDER_ID
                        ,ORDER_TYPE
                        ,SCP_TARGET_ID    
                        ,DEMAND_ID        
                        ,ITEM_ID  
                        ,LANE_QTY
                        ,TOP_ITEM_ID      
                        ,TOP_WORK_ORDER_ID
                        ,LINE_ID          
                        ,OPERATION_ID   
                        ,ELECTRODE_TYPE
                        ,WORK_CENTER_ID   
                        ,EQUIPMENT_ID     
                        ,PLAN_DATE        
                        ,START_TIME       
                        ,END_TIME         
                        ,PLAN_QTY         
                        ,PLAN_IN_QTY      
                        ,FIX_TYPE         
                        ,PRODUCTION_TYPE  
                        ,BOM_VERSION_ID   
                        ,INSERT_ID        
                        ,INSERT_TIME   
                      )                      
            SELECT  A.INSTANCE_ID
                  , A.FP_PLAN_ID
                  , A.COMPANY_ID
                  , A.DIVISION_ID
                  , A.SITE_ID
                  , A.PLANT_ID
                  , A.FACTORY_ID
                  , A.WORK_ORDER_SPL_ID  + '#' + CONVERT(nvarchar, SEQ) AS WORK_ORDER_SPL_ID
                  , A.WORK_ORDER_ID
                  , A.BATCH_ORDER_ID
                  , A.BIN_ORDER_ID
                  , A.ORDER_TYPE
                  , A.SCP_TARGET_ID
                  , A.DEMAND_ID
                  , A.ITEM_ID
                  , A.LANE_QTY
                  , A.TOP_ITEM_ID
                  , A.TOP_WORK_ORDER_ID
                  , A.LINE_ID
                  , A.OPERATION_ID
                  , A.ELECTRODE_TYPE
                  , A.WORK_CENTER_ID
                  , A.RESOURCE_ID AS EQUIPMENT_ID
                  , CONVERT(datetime2, dbo.fn_set_work_date2(@v_master_id, @v_plan_id, ISNULL(RUN_START_TIME, START_TIME), ISNULL(RUN_END_TIME,   END_TIME)), 112) AS plan_date
                  , ISNULL(RUN_START_TIME, START_TIME) AS START_TIME
                  , ISNULL(RUN_END_TIME,   END_TIME)   AS END_TIME
                  , CASE WHEN TOTAL_RUN_TIME = 0 THEN PLAN_QTY    ELSE (PLAN_QTY    * (RUN_TIME / TOTAL_RUN_TIME)) END AS PLAN_QTY
                  , CASE WHEN TOTAL_RUN_TIME = 0 THEN PLAN_IN_QTY ELSE (PLAN_IN_QTY * (RUN_TIME / TOTAL_RUN_TIME)) END AS PLAN_IN_QTY
                  , A.FIX_TYPE
                  , A.PRODUCTION_TYPE
                  , NULL AS BOM_VERSION_ID
                  , @v_proc_name    AS INSERT_ID
                  , GETDATE()       AS INSERT_TIME
            FROM   (
                    SELECT A.*,
                           SUM(RUN_TIME) OVER(PARTITION BY WORK_ORDER_ID) AS TOTAL_RUN_TIME
                    FROM   ( 
                            SELECT A.*,
                                   B.RUN_START_TIME, B.RUN_END_TIME,
                                   CASE WHEN CAPA_TYPE = 'TACT' THEN ISNULL(B.RUN_SECOND - B.OFF_SECOND, DATEDIFF(SS, A.START_TIME, A.END_TIME)) 
                                        ELSE 1000   -- TAT_MOVE 인 경우 RUNTIME 이 0 , 위 / DIVIDED 0  에러 발생을 방지하기 위함
                                   END AS RUN_TIME
                            FROM   (
                                    SELECT A.*, C.EQUIPMENT_ID AS RESOURCE_ID, C.WORK_CENTER_ID, C.SEQ, C.CNT, D.CAPA_TYPE
                                    FROM  (
                                            SELECT       
                                                    A.INSTANCE_ID
                                                  , A.FP_PLAN_ID
                                                  , A.COMPANY_ID
                                                  , A.DIVISION_ID
                                                  , A.SITE_ID
                                                  , A.PLANT_ID
                                                  , A.FACTORY_ID
                                                  , A.WORK_ORDER_SPL_ID
                                                  , A.WORK_ORDER_ID
                                                  , A.BATCH_ORDER_ID
                                                  , A.BIN_ORDER_ID
                                                  , A.ORDER_TYPE
                                                  , A.SCP_TARGET_ID
                                                  , A.DEMAND_ID
                                                  , A.ITEM_ID
                                                  , A.LANE_QTY
                                                  , A.TOP_ITEM_ID
                                                  , A.TOP_WORK_ORDER_ID
                                                  , A.LINE_ID
                                                  , A.OPERATION_ID
                                                  , A.ELECTRODE_TYPE
                                                  , A.EQUIPMENT_ID
                                                  , A.PLAN_DATE
                                                  , A.START_TIME
                                                  , A.END_TIME
                                                  , A.PLAN_QTY
                                                  , A.PLAN_IN_QTY
                                                  , A.FIX_TYPE
                                                  , A.PRODUCTION_TYPE
                                            FROM    TH_BUF_SCM_PRODUCTION A
                                            WHERE   INSTANCE_ID = @v_master_id
                                            AND     FP_PLAN_ID = @v_plan_id
                                            AND     FACTORY_ID != 'VIRTUAL_LANE'
                                            /*
                                            AND     NOT EXISTS (  SELECT 1
                                                                  FROM   (
                                                                          SELECT 
                                                                                  B.WORK_ORDER_ID as WORK_ORDER_ID
                                                                                , a.PO_TYPE
                                                                          FROM    TH_MST_FIXED_PLAN  AS A,
                                                                                  TH_ENG_FIXED_PLAN  AS B
                                                                          WHERE   a.MASTER_ID = @v_master_id 
                                                                          AND     a.PLAN_ID = @v_plan_id
                                                                          AND     A.MASTER_ID = B.MASTER_ID
                                                                          AND     A.PLAN_ID = B.PLAN_ID
                                                                          AND     A.WORK_ORDER_ID = ISNULL(B.DESCR, B.WORK_ORDER_ID)                                                                  
                                                                         ) X 
                                                                  WHERE  X.PO_TYPE = 'REPLAN'
                                                                  AND    X.WORK_ORDER_ID = A.WORK_ORDER_ID )
                                            */
                                          ) A
                                          INNER JOIN 
                                                          (
                                                            SELECT COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID,
                                                                   EQUIPMENT_ID, OPERATION_ID, LINE_ID, ELECTRODE_TYPE,
                                                                   ISNULL(WORK_CENTER_ID,'-') AS WORK_CENTER_ID,
                                                                   LINE_ID +'_'+ OPERATION_ID
                                                                               + CASE WHEN ELECTRODE_TYPE IN ('','-') THEN ''
                                                                                      ELSE '_'+ ELECTRODE_TYPE
                                                                                 END  FP_EQUIPMENT_ID,
                                                                   ROW_NUMBER() OVER (PARTITION BY COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID,
                                                                                                   OPERATION_ID, LINE_ID, ELECTRODE_TYPE
                                                                                      ORDER     BY EQUIPMENT_ID) SEQ,
                                                                   COUNT(1)     OVER (PARTITION BY COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID,
                                                                                                   OPERATION_ID, LINE_ID, ELECTRODE_TYPE) CNT
                                                            FROM   SY_SCM_EQUIPMENT_M
                                                            WHERE  ACTIVE_FLAG = 'Y'
                                                            AND    EQUIPMENT_TYPE = 'M'
                                                            UNION  ALL
                                                            -- 종속 라인 부분 추가..
                                                            SELECT COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID,
                                                                   EQUIPMENT_ID, OPERATION_ID, LINE_ID, ELECTRODE_TYPE,
                                                                   ISNULL(WORK_CENTER_ID,'-') AS WORK_CENTER_ID,
                                                                   LINE_ID +'_'+ OPERATION_ID
                                                                               + CASE WHEN ELECTRODE_TYPE IN ('','-') THEN ''
                                                                                      ELSE '_'+ ELECTRODE_TYPE
                                                                                 END  
                                                                           +'_'+ EQUIPMENT_ID AS FP_EQUIPMENT_ID,
                                                                   1 SEQ,
                                                                   1 CNT
                                                            FROM   SY_SCM_EQUIPMENT_M
                                                            WHERE  ACTIVE_FLAG = 'Y'
                                                            AND    EQUIPMENT_TYPE = 'M'
                                                          ) C
                                                ON    A.COMPANY_ID = C.COMPANY_ID
                           AND   A.DIVISION_ID = C.DIVISION_ID
                                                AND   A.SITE_ID = C.SITE_ID
                                                AND   A.PLANT_ID = C.PLANT_ID
                                                AND   A.FACTORY_ID = C.FACTORY_ID
                                          INNER JOIN SY_SCM_OPERATION_M D
                                                ON    A.EQUIPMENT_ID = C.FP_EQUIPMENT_ID
                                                AND   A.COMPANY_ID = D.COMPANY_ID
                                                AND   A.DIVISION_ID = D.DIVISION_ID
                                                AND   A.SITE_ID = D.SITE_ID
                                                AND   A.OPERATION_ID = D.OPERATION_ID
                               ) A
                               LEFT OUTER JOIN TH_BUF_SCM_PRODUCTION_OFF_RUN B
                                    ON    A.WORK_ORDER_ID = B.WORK_ORDER_ID
                                    AND   A.RESOURCE_ID = B.EQUIPMENT_ID
                                    AND   B.RUN_START_TIME < B.RUN_END_TIME
                           ) A
                   ) A
                      

          END
   
            --LOG 생성
            SET @v_message = @@ROWCOUNT
            SET @n_log_count += 1
            EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN_EQUIPMENT', 'INSERT', @n_log_count, null, @v_message, null 


        END

      ELSE
      
        BEGIN
        
          DELETE FROM TH_EXP_PRODUCTION_PLAN_EQUIPMENT
          WHERE  INSTANCE_ID = @v_master_id
          AND    FP_PLAN_ID = @v_plan_id

          SET @v_message = @@ROWCOUNT
          SET @n_log_count += 1
          EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN_EQUIPMENT', 'DELETE', @n_log_count, null, @v_message, null 

          INSERT INTO TH_EXP_PRODUCTION_PLAN_EQUIPMENT
                (
                  INSTANCE_ID
                , FP_PLAN_ID
                , COMPANY_ID
                , DIVISION_ID
                , SITE_ID
                , PLANT_ID
                , FACTORY_ID
                , WORK_ORDER_SPL_ID
                , WORK_ORDER_ID
                , BATCH_ORDER_ID
                , BIN_ORDER_ID
                , ORDER_TYPE
                , SCP_TARGET_ID
                , DEMAND_ID
                , ITEM_ID
                , LANE_QTY
                , TOP_ITEM_ID
                , LINE_ID
                , OPERATION_ID
                , ELECTRODE_TYPE
                , WORK_CENTER_ID
                , EQUIPMENT_ID
                , PLAN_DATE
                , START_TIME
                , END_TIME
                , PLAN_QTY
                , PLAN_IN_QTY
                , FIX_TYPE
                , PRODUCTION_TYPE
                , INSERT_ID
                , INSERT_TIME
                )
          SELECT       
                  A.INSTANCE_ID
                , A.FP_PLAN_ID
                , A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , A.FACTORY_ID
                , A.WORK_ORDER_SPL_ID
                , A.WORK_ORDER_ID
                , A.BATCH_ORDER_ID
                , A.BIN_ORDER_ID
                , A.ORDER_TYPE
                , A.SCP_TARGET_ID
                , A.DEMAND_ID
                , A.ITEM_ID
                , A.LANE_QTY
                , A.TOP_ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , A.ELECTRODE_TYPE
                , A.WORK_CENTER_ID
                , A.EQUIPMENT_ID
                , A.PLAN_DATE
                , A.START_TIME
                , A.END_TIME
                , A.PLAN_QTY
                , A.PLAN_IN_QTY
                , CASE WHEN C.WORK_ORDER_ID IS NOT NULL THEN 'F' ELSE A.FIX_TYPE END FIX_TYPE
                , PRODUCTION_TYPE
                , @v_proc_name    AS INSERT_ID
                , GETDATE()       AS INSERT_TIME
          FROM    TH_BUF_SCM_PRODUCTION A
                  LEFT  OUTER JOIN TH_MST_FIXED_PLAN C
                        ON    A.INSTANCE_ID = C.MASTER_ID
                        AND   A.FP_PLAN_ID = C.PLAN_ID
                        AND   A.WORK_ORDER_ID = C.WORK_ORDER_ID
                        AND   C.PO_TYPE IN ('FIX','REPLAN')
          WHERE   INSTANCE_ID = @v_master_id
          AND     FP_PLAN_ID = @v_plan_id
          AND     FACTORY_ID != 'VIRTUAL_LANE'
        
          SET @v_message = @@ROWCOUNT
          SET @n_log_count += 1
          EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN_EQUIPMENT', 'INSERT', @n_log_count, null, @v_message, null 
---------------------------------------------------------------------------------------------------------
-- LINE 계획일 경우 설비 수 만큼 N 빵하는 로직 주석처리함.
---------------------------------------------------------------------------------------------------------
*/

      ---------------------------------------------------------------------------------------
      -- LINE 계획이면 대표설비 1개로, 설정하여 계획 수립
      ---------------------------------------------------------------------------------------
      BEGIN

        DELETE FROM TH_EXP_PRODUCTION_PLAN
        WHERE  INSTANCE_ID = @v_master_id
        AND    FP_PLAN_ID = @v_plan_id

        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN', 'DELETE', @n_log_count, null, @v_message, null 

        INSERT INTO TH_EXP_PRODUCTION_PLAN
              (
                INSTANCE_ID
              , FP_PLAN_ID
              , COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              --, WORK_ORDER_SPL_ID
              , WORK_ORDER_ID
              , BATCH_ORDER_ID
              , BIN_ORDER_ID
              , ORDER_TYPE
              , SCP_TARGET_ID
              , DEMAND_ID
              , ITEM_ID
              , LANE_QTY
              , TOP_ITEM_ID
              , LINE_ID
              , OPERATION_ID
              , ELECTRODE_TYPE
              , WORK_CENTER_ID
              --, EQUIPMENT_ID
              , PLAN_DATE
              , START_TIME
              , END_TIME
              , PLAN_QTY
              , PLAN_IN_QTY
              , FIX_TYPE
              , PRODUCTION_TYPE
              , LANE_TACT_QTY
              , INSERT_ID
              , INSERT_TIME
              )
        SELECT       
                A.INSTANCE_ID
              , A.FP_PLAN_ID
              , A.COMPANY_ID
              , A.DIVISION_ID
              , A.SITE_ID
              , A.PLANT_ID
              , A.FACTORY_ID
              --, A.WORK_ORDER_SPL_ID
              , A.WORK_ORDER_SPL_ID
              , A.BATCH_ORDER_ID
              , A.BIN_ORDER_ID
              , A.ORDER_TYPE
              , A.SCP_TARGET_ID
              , A.DEMAND_ID
              , A.ITEM_ID
              , A.LANE_QTY
              , A.TOP_ITEM_ID
              , A.LINE_ID
              , A.OPERATION_ID
              , A.ELECTRODE_TYPE
              , A.WORK_CENTER_ID
              --, A.EQUIPMENT_ID
              , A.PLAN_DATE
              , A.START_TIME
              , A.END_TIME
              , A.PLAN_QTY
              , A.PLAN_IN_QTY
              , CASE WHEN C.WORK_ORDER_ID IS NOT NULL THEN 'F' ELSE A.FIX_TYPE END FIX_TYPE
              , A.PRODUCTION_TYPE
              , A.LANE_TACT_QTY
              , @v_proc_name    AS INSERT_ID
              , GETDATE()       AS INSERT_TIME
        FROM    TH_BUF_SCM_PRODUCTION A
                LEFT  OUTER JOIN TH_MST_FIXED_PLAN C
                      ON    A.INSTANCE_ID = C.MASTER_ID
   AND   A.FP_PLAN_ID = C.PLAN_ID
                      AND   A.WORK_ORDER_ID = C.WORK_ORDER_ID
                      AND   C.PO_TYPE IN ('FIX','REPLAN')
        WHERE   A.INSTANCE_ID = @v_master_id
        AND     A.FP_PLAN_ID = @v_plan_id
        AND     FACTORY_ID != 'VIRTUAL_LANE'

        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN', 'INSERT', @n_log_count, null, @v_message, null 
    
        DELETE FROM TH_EXP_PRODUCTION_PLAN_EQUIPMENT
        WHERE  INSTANCE_ID = @v_master_id
        AND    FP_PLAN_ID = @v_plan_id

        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN_EQUIPMENT', 'DELETE', @n_log_count, null, @v_message, null 

        INSERT INTO TH_EXP_PRODUCTION_PLAN_EQUIPMENT
              (
                INSTANCE_ID
              , FP_PLAN_ID
              , COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , WORK_ORDER_SPL_ID
              , WORK_ORDER_ID
              , BATCH_ORDER_ID
              , BIN_ORDER_ID
              , ORDER_TYPE
              , SCP_TARGET_ID
              , DEMAND_ID
              , ITEM_ID
              , LANE_QTY
              , TOP_ITEM_ID
              , LINE_ID
              , OPERATION_ID
              , ELECTRODE_TYPE
              , WORK_CENTER_ID
              , EQUIPMENT_ID
              , PLAN_DATE
              , START_TIME
              , END_TIME
              , PLAN_QTY
              , PLAN_IN_QTY
              , FIX_TYPE
              , PRODUCTION_TYPE
              , INSERT_ID
              , INSERT_TIME
              )
        SELECT       
                A.INSTANCE_ID
              , A.FP_PLAN_ID
              , A.COMPANY_ID
              , A.DIVISION_ID
              , A.SITE_ID
              , A.PLANT_ID
              , A.FACTORY_ID
              , A.WORK_ORDER_SPL_ID
              , A.WORK_ORDER_ID
              , A.BATCH_ORDER_ID
              , A.BIN_ORDER_ID
              , A.ORDER_TYPE
              , A.SCP_TARGET_ID
              , A.DEMAND_ID
              , A.ITEM_ID
              , A.LANE_QTY
              , A.TOP_ITEM_ID
              , A.LINE_ID
              , A.OPERATION_ID
              , A.ELECTRODE_TYPE
              , A.WORK_CENTER_ID
              , ISNULL(D.EQUIPMENT_ID, A.EQUIPMENT_ID) AS EQUIPMENT_ID
              , A.PLAN_DATE
              , A.START_TIME
              , A.END_TIME
              , A.PLAN_QTY
              , A.PLAN_IN_QTY
              , CASE WHEN C.WORK_ORDER_ID IS NOT NULL THEN 'F' ELSE A.FIX_TYPE END FIX_TYPE
              , PRODUCTION_TYPE
              , @v_proc_name    AS INSERT_ID
              , GETDATE()       AS INSERT_TIME
        FROM    TH_BUF_SCM_PRODUCTION A
                LEFT  OUTER JOIN TH_MST_FIXED_PLAN C
                      ON    A.INSTANCE_ID = C.MASTER_ID
                      AND   A.FP_PLAN_ID = C.PLAN_ID
                      AND   A.WORK_ORDER_ID = C.WORK_ORDER_ID
                      AND   C.PO_TYPE IN ('FIX','REPLAN')
                LEFT  OUTER JOIN (
                                  SELECT A.FACTORY_ID, A.LINE_ID, A.OPERATION_ID, A.ELECTRODE_TYPE
                                       , A.RESOURCE_ID, A.EQUIPMENT_ID
                                  FROM   (
                                          SELECT FACTORY_ID, LINE_ID, OPERATION_ID, ELECTRODE_TYPE, EQUIPMENT_ID
                                               , LINE_ID + '_' + OPERATION_ID
                                                               + CASE WHEN ELECTRODE_TYPE = '-'   THEN ''
                                                                      WHEN ELECTRODE_TYPE = ''    THEN ''
                                  WHEN ELECTRODE_TYPE IS NULL THEN ''
                                                                      ELSE '_' + ELECTRODE_TYPE
                                                                 END
                                                 AS RESOURCE_ID
                                               , DENSE_RANK() OVER (PARTITION BY FACTORY_ID, LINE_ID, OPERATION_ID, ELECTRODE_TYPE
                                                                    ORDER     BY FACTORY_ID
                                                                               , CASE WHEN LINE_ID = 'A1A08' AND MES_LINE_ID = 'A1A08' THEN 1 ELSE 9 END
                                                                               , EQUIPMENT_ID) AS SEQ
                                          FROM   SY_SCM_EQUIPMENT_M
                                          WHERE  ACTIVE_FLAG = 'Y'
                                          AND    EQUIPMENT_TYPE = 'M'
                                         ) A
                                  WHERE  SEQ = 1    -- ## 대표설비만...                      
                                 ) D
                      ON    A.FACTORY_ID      = D.FACTORY_ID
                      AND   A.LINE_ID         = D.LINE_ID
                      AND   A.OPERATION_ID    = D.OPERATION_ID
                      AND   A.ELECTRODE_TYPE  = D.ELECTRODE_TYPE
                      AND   A.EQUIPMENT_ID    = D.RESOURCE_ID
        WHERE   A.INSTANCE_ID = @v_master_id
        AND     A.FP_PLAN_ID = @v_plan_id
        AND     A.FACTORY_ID != 'VIRTUAL_LANE'
      
        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN_EQUIPMENT', 'INSERT', @n_log_count, null, @v_message, null 
      
      END

      -- TOP_WORK_ORDER_ID UPDATE
      BEGIN

        UPDATE TH_EXP_PRODUCTION_PLAN_EQUIPMENT
        SET    TH_EXP_PRODUCTION_PLAN_EQUIPMENT.TOP_WORK_ORDER_ID = A.WORK_ORDER_ID
        FROM   TH_BUF_SCM_PRODUCTION A,
               TH_EXP_PRODUCTION_PLAN_EQUIPMENT B
        WHERE  A.INSTANCE_ID = B.INSTANCE_ID
        AND    A.FP_PLAN_ID = B.FP_PLAN_ID
        AND    A.TOP_ITEM_ID = B.TOP_ITEM_ID
        AND    A.TOP_ITEM_ID = A.ITEM_ID
        AND    A.INSTANCE_ID = @v_master_id
        AND    A.FP_PLAN_ID = @v_plan_id

        SET @v_message = 'TOP_WORK_ORDER_ID - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN_EQUIPMENT', 'UPDATE', @n_log_count, null, @v_message, null 

        UPDATE TH_EXP_PRODUCTION_PLAN_EQUIPMENT
        SET    TH_EXP_PRODUCTION_PLAN_EQUIPMENT.TOP_WORK_ORDER_ID = B.WORK_ORDER_ID
        FROM   TH_EXP_PRODUCTION_PLAN_EQUIPMENT A,
               (
                SELECT A.DEMAND_ID, A.WORK_ORDER_ID
                FROM   TH_EXP_PRODUCTION_PLAN_EQUIPMENT A,
                       TH_DPP_NET_DEMAND B
                WHERE  A.INSTANCE_ID        = B.MASTER_ID
                AND    A.FP_PLAN_ID         = B.PLAN_ID
                AND    A.DEMAND_ID          = B.NET_DEMAND_ID
                AND    A.TOP_ITEM_ID        = B.SALES_MODEL
                AND    A.ITEM_ID            = B.ITEM_ID
                AND    A.INSTANCE_ID        = @v_master_id
                AND    A.FP_PLAN_ID         = @v_plan_id
                AND    A.TOP_WORK_ORDER_ID  IS NULL
               ) B
        WHERE  A.INSTANCE_ID      = @v_master_id
        AND    A.FP_PLAN_ID       = @v_plan_id
        AND    A.DEMAND_ID        = B.DEMAND_ID
        AND    A.TOP_WORK_ORDER_ID IS NULL

        SET @v_message = 'TOP_WORK_ORDER_ID - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN_EQUIPMENT', 'UPDATE', @n_log_count, null, @v_message, null 

      END
      
