      ------------------------------------------------------------------------------------
      /**/
      DELETE FROM TH_EXP_DAILY_PRODUCTION_PLAN
      WHERE  INSTANCE_ID = @v_master_id
      AND    FP_PLAN_ID = @v_plan_id

      SET @v_message = @@ROWCOUNT
      SET @n_log_count += 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DAILY_PRODUCTION_PLAN', 'DELETE', @n_log_count, null, @v_message, null 

      -- BATCH 설비를 제외한 나머지 오더에 대해서는 WORK_ORDER_SPL 로
      INSERT INTO TH_EXP_DAILY_PRODUCTION_PLAN
            (
              INSTANCE_ID
            , FP_PLAN_ID
            , COMPANY_ID
            , DIVISION_ID
            , SITE_ID
            , PLANT_ID
            , FACTORY_ID
            , WORK_ORDER_SPL_ID
            , WORK_ORDER_ID
            , ORG_DEMAND_ID
            , DEMAND_ID
            , ITEM_ID
            , TOP_ITEM_ID
            , OPERATION_ID
            , LINE_ID
            , ELECTRODE_TYPE
            , EQUIPMENT_ID
            , PLAN_DATE
            , START_TIME
            , END_TIME
            , PLAN_QTY
            , PLAN_IN_QTY
            , PLAN_LATE_QTY
            , FIX_TYPE
            , PRODUCTION_TYPE
            , TOTAL_WORKING_TIME
            , LINE_ITEM_SEQ
            , OPERATION_ITEM_SEQ
            , INSERT_ID
            , INSERT_DTTM            
            )          
      SELECT  A.MASTER_ID       AS INSTANCE_ID
            , A.PLAN_ID         AS FP_PLAN_ID
            , A.IRS_ATTB_11     AS COMPANY_ID
            , A.IRS_ATTB_12     AS DIVISION_ID
            , A.IRS_ATTB_13     AS SITE_ID
            , A.IRS_ATTB_14     AS PLANT_ID
            , A.SITE_ID         AS FACTORY_ID
            --, REPLACE(A.WORK_ORDER_ID, A.ORG_WORK_ORDER_ID, B.PLAN_ORDER_ID) AS WORK_ORDER_SPL_ID
            , B.PLAN_ORDER_ID  
                  + CASE WHEN SPLIT_ORDER_SEQ = 0 THEN '' 
                         WHEN SPLIT_ORDER_SEQ < 10 THEN '#00' + CONVERT(NVARCHAR, SPLIT_ORDER_SEQ)
                         WHEN SPLIT_ORDER_SEQ < 100 THEN '#0' + CONVERT(NVARCHAR, SPLIT_ORDER_SEQ)
           WHEN SPLIT_ORDER_SEQ < 1000 THEN '#' + CONVERT(NVARCHAR, SPLIT_ORDER_SEQ)
                    END  AS WORK_ORDER_SPL_ID
            , B.PLAN_ORDER_ID   AS WORK_ORDER_ID
            , B.ORG_DEMAND_ID
            , B.DEMAND_ID
            , A.ITEM_ID
            , D.SALES_MODEL     AS TOP_ITEM_ID
            , A.OPERATION_ID
            , A.ROUTE_ID        AS LINE_ID
            , ISNULL(C.RES_ATTB_20, '-') AS ELECTRODE_TYPE
            , A.RESOURCE_ID     AS EQUIPMENT_ID
            , CONVERT(datetime2, dbo.fn_set_work_date2(a.master_id, a.plan_id, a.start_time, a.end_time), 112) AS plan_date
            , A.START_TIME
            , A.END_TIME
            , A.COMPLETE_QTY    AS PLAN_QTY
            , A.OPERATION_QTY   AS PLAN_IN_QTY
            , 0                 AS PLAN_LATE_QTY
            , CASE WHEN E.WORK_ORDER_ID IS NOT NULL THEN 'F' ELSE '' END AS FIX_TYPE
            , D.ORDER_TYPE      AS PRODUCTION_TYPE
            , A.TOTAL_WORKING_TIME
            , A.LINE_ITEM_SEQ
            , A.OPERATION_ITEM_SEQ
            , @v_proc_name      AS INSERT_ID
            , GETDATE()         AS INSERT_TIME
      FROM    (
              SELECT A.*
                   , DENSE_RANK() OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID
                                        ORDER     BY A.MIN_ITEM_SEQ) AS LINE_ITEM_SEQ
                   , DENSE_RANK() OVER (PARTITION BY A.IRS_ATTB_11, A.IRS_ATTB_12, A.IRS_ATTB_13, A.OPERATION_ID
                                        ORDER     BY A.MIN_OP_SEQ, A.ITEM_ID) AS OPERATION_ITEM_SEQ
              FROM   (
                      SELECT A.*
                           , MIN(LINE_SEQ)      OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID) MIN_ITEM_SEQ
                           , MIN(OPERATION_SEQ) OVER (PARTITION BY A.IRS_ATTB_11, A.IRS_ATTB_12, A.IRS_ATTB_13, A.OPERATION_ID, A.ITEM_ID) MIN_OP_SEQ
                      FROM   (
                              SELECT A.*
                                   , DENSE_RANK() OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID
                                                        ORDER     BY A.MIN_LINE_ITEM_START_TIME
                                                                   , A.MIN_LINE_ITEM_END_TIME
                                                                   , A.MAX_LINE_ITEM_END_TIME
                                                                   , A.MAX_LINE_ITEM_START_TIME
                                                                   , A.WORK_ORDER_ID) LINE_SEQ
                                   , DENSE_RANK() OVER (PARTITION BY A.IRS_ATTB_11, A.IRS_ATTB_12, A.IRS_ATTB_13, A.OPERATION_ID
                                                        ORDER     BY A.MIN_OP_ITEM_START_TIME
                                                                   , A.MIN_OP_ITEM_END_TIME
                                                                   , A.MAX_OP_ITEM_END_TIME
                                                                   , A.MAX_OP_ITEM_START_TIME
                                                                   , A.WORK_ORDER_ID) OPERATION_SEQ
                              FROM   (
                                      SELECT  A.*
                                            , DENSE_RANK() OVER (PARTITION BY A.ORG_WORK_ORDER_ID ORDER BY A.START_TIME, A.WORK_ORDER_ID) - 1 SPLIT_ORDER_SEQ
                                            , B.IRS_ATTB_11
                                            , B.IRS_ATTB_12
                                            , B.IRS_ATTB_13
                                            , B.IRS_ATTB_14
                                            , MIN(START_TIME) OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID) MIN_LINE_ITEM_START_TIME
                                            , MAX(START_TIME) OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID) MAX_LINE_ITEM_START_TIME
                                            , MIN(END_TIME)   OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID) MIN_LINE_ITEM_END_TIME
                                            , MAX(END_TIME)   OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID) MAX_LINE_ITEM_END_TIME
                                            , MIN(START_TIME) OVER (PARTITION BY B.IRS_ATTB_11, B.IRS_ATTB_12, B.IRS_ATTB_13, A.OPERATION_ID, A.ITEM_ID) MIN_OP_ITEM_START_TIME
                                            , MAX(START_TIME) OVER (PARTITION BY B.IRS_ATTB_11, B.IRS_ATTB_12, B.IRS_ATTB_13, A.OPERATION_ID, A.ITEM_ID) MAX_OP_ITEM_START_TIME
                                            , MIN(END_TIME)   OVER (PARTITION BY B.IRS_ATTB_11, B.IRS_ATTB_12, B.IRS_ATTB_13, A.OPERATION_ID, A.ITEM_ID) MIN_OP_ITEM_END_TIME
                                            , MAX(END_TIME)   OVER (PARTITION BY B.IRS_ATTB_11, B.IRS_ATTB_12, B.IRS_ATTB_13, A.OPERATION_ID, A.ITEM_ID) MAX_OP_ITEM_END_TIME                                             
                                      FROM    TH_BUF_OUT_WORK_ORDER_SPL A,
                                              TH_MST_ITEM_ROUTE_SITE B
                                      WHERE   A.MASTER_ID       = @v_master_id
                                      AND     A.PLAN_ID         = @v_plan_id
                                      AND     A.OUT_VERSION_ID  = @v_out_version_id
                                      AND     A.MASTER_ID       = B.MASTER_ID
                                      AND     A.PLAN_ID         = B.PLAN_ID
                                      AND     A.ITEM_ID         = B.ITEM_ID
                                      AND     A.SITE_ID         = B.SITE_ID
                                      AND     A.ROUTE_ID        = B.ROUTE_ID
                                      AND     A.OPERATION_ID    = B.OPERATION_ID
                                      AND     NOT EXISTS (
                                                          SELECT 1
                                                          FROM   (
                                                                  SELECT RESOURCE_ID
                                                                  FROM   TH_ENG_RESOURCE
                                                                  WHERE  MASTER_iD = @v_master_id
                                                                  AND    PLAN_ID = @v_plan_id
                                                                  AND    BATCH_TYPE = 'BATCH'
                                                                  UNION  ALL
                                                                  SELECT RESOURCE_ID
                                                                  FROM   TH_ENG_RESOURCE A
                                                                  WHERE  MASTER_iD = @v_master_id
                                                                  AND    PLAN_ID = @v_plan_id
                                                                  AND    MASTER_ID NOT IN ('KR_SRS')
                                                                  AND    EXISTS (
                                                                                  SELECT 1
                                                                                  FROM   TH_MST_OP_RESOURCE B
                                                                                  WHERE  A.MASTER_ID = B.MASTER_ID
                                                                                  AND    A.PLAN_ID = B.PLAN_ID
                                                                                  AND    A.RESOURCE_ID = B.RESOURCE_ID
                                                                                  AND    B.OPERATION_ID IN ('E2000','S2000')
                                                                                )
                                                 ) X                                                                
                                                          WHERE  X.RESOURCE_ID = A.RESOURCE_ID
                                                         )                                      
                                     ) A
                             ) A
                     ) A      
              ) A
            , TH_EXP_PLANORDER      B
              LEFT  OUTER JOIN TH_MST_FIXED_PLAN E
                    ON    B.MASTER_ID = E.MASTER_ID
                    AND   B.PLAN_ID   = E.PLAN_ID
                    AND   B.PLAN_ORDER_ID = E.WORK_ORDER_ID
                    AND   E.PO_TYPE IN ('FIX','REPLAN')
            , TH_MST_RESOURCE       C
            , TH_DPP_NET_DEMAND     D
      WHERE   A.MASTER_ID         = @v_master_id
      AND     A.PLAN_ID           = @v_plan_id
      AND     A.OUT_VERSION_ID    = @v_out_version_id
      AND     A.MASTER_ID         = B.MASTER_ID
      AND     A.PLAN_ID           = B.PLAN_ID
      AND     A.ORG_WORK_ORDER_ID = B.ORDER_ID
      AND     A.MASTER_ID         = C.MASTER_ID
      AND     A.PLAN_ID           = C.PLAN_ID
      AND     A.RESOURCE_ID       = C.RESOURCE_ID
      AND     A.MASTER_ID         = D.MASTER_ID
      AND     A.PLAN_ID           = D.PLAN_ID
      AND     B.DEMAND_ID         = D.NET_DEMAND_ID
      AND     A.SITE_ID          != 'VIRTUAL_LANE'
      
      SET @v_message = @@ROWCOUNT
      SET @n_log_count += 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DAILY_PRODUCTION_PLAN', 'INSERT', @n_log_count, null, @v_message, null 


      -- BATCH 설비는 WORK ORDER 로
      INSERT INTO TH_EXP_DAILY_PRODUCTION_PLAN
            (
              INSTANCE_ID
            , FP_PLAN_ID
            , COMPANY_ID
            , DIVISION_ID
            , SITE_ID
            , PLANT_ID
            , FACTORY_ID
            , WORK_ORDER_SPL_ID
            , WORK_ORDER_ID
            , ORG_DEMAND_ID
            , DEMAND_ID
            , ITEM_ID
            , TOP_ITEM_ID
            , OPERATION_ID
            , LINE_ID
            , ELECTRODE_TYPE
            , EQUIPMENT_ID
            , PLAN_DATE
            , START_TIME
            , END_TIME
            , PLAN_QTY
            , PLAN_IN_QTY
            , PLAN_LATE_QTY
            , FIX_TYPE
            , PRODUCTION_TYPE
            , TOTAL_WORKING_TIME
            , LINE_ITEM_SEQ
            , OPERATION_ITEM_SEQ
            , INSERT_ID
            , INSERT_DTTM            
            )          
      SELECT  A.MASTER_ID       AS INSTANCE_ID
            , A.PLAN_ID         AS FP_PLAN_ID
            , A.IRS_ATTB_11     AS COMPANY_ID
            , A.IRS_ATTB_12     AS DIVISION_ID
            , A.IRS_ATTB_13     AS SITE_ID
            , A.IRS_ATTB_14     AS PLANT_ID
            , A.SITE_ID         AS FACTORY_ID
            , B.PLAN_ORDER_ID  
                  + CASE WHEN SPLIT_ORDER_SEQ = 0 THEN '' 
                         WHEN SPLIT_ORDER_SEQ < 10 THEN '#00' + CONVERT(NVARCHAR, SPLIT_ORDER_SEQ)
                         WHEN SPLIT_ORDER_SEQ < 100 THEN '#0' + CONVERT(NVARCHAR, SPLIT_ORDER_SEQ)
                         WHEN SPLIT_ORDER_SEQ < 1000 THEN '#' + CONVERT(NVARCHAR, SPLIT_ORDER_SEQ)
                    END  AS WORK_ORDER_SPL_ID
            , B.PLAN_ORDER_ID   AS WORK_ORDER_ID
            , B.ORG_DEMAND_ID
            , B.DEMAND_ID
            , A.ITEM_ID
            , D.SALES_MODEL     AS TOP_ITEM_ID
            , A.OPERATION_ID
            , A.ROUTE_ID        AS LINE_ID
            , ISNULL(C.RES_ATTB_20, '-') AS ELECTRODE_TYPE
            , A.RESOURCE_ID     AS EQUIPMENT_ID
            , CONVERT(datetime2, dbo.fn_set_work_date2(a.master_id, a.plan_id, a.start_time, a.end_time), 112) AS plan_date
            , A.START_TIME
            , A.END_TIME
            , A.COMPLETE_QTY    AS PLAN_QTY
            , A.OPERATION_QTY   AS PLAN_IN_QTY
            , 0                 AS PLAN_LATE_QTY
            , CASE WHEN E.WORK_ORDER_ID IS NOT NULL THEN 'F' ELSE '' END AS FIX_TYPE
            , D.ORDER_TYPE      AS PRODUCTION_TYPE
            , A.TOTAL_WORKING_TIME
            , A.LINE_ITEM_SEQ
            , A.OPERATION_ITEM_SEQ
            , @v_proc_name      AS INSERT_ID
            , GETDATE()         AS INSERT_TIME
      FROM    (
              SELECT A.*
                   , DENSE_RANK() OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID
                                        ORDER     BY A.MIN_ITEM_SEQ) AS LINE_ITEM_SEQ
                   , DENSE_RANK() OVER (PARTITION BY A.IRS_ATTB_11, A.IRS_ATTB_12, A.IRS_ATTB_13, A.OPERATION_ID
                                        ORDER     BY A.MIN_OP_SEQ, A.ITEM_ID) AS OPERATION_ITEM_SEQ
              FROM   (
                      SELECT A.*
                           , MIN(LINE_SEQ)      OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID) MIN_ITEM_SEQ
                           , MIN(OPERATION_SEQ) OVER (PARTITION BY A.IRS_ATTB_11, A.IRS_ATTB_12, A.IRS_ATTB_13, A.OPERATION_ID, A.ITEM_ID) MIN_OP_SEQ
                      FROM   (
                              SELECT A.*
                                   , DENSE_RANK() OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID
                                                        ORDER     BY A.MIN_LINE_ITEM_START_TIME
                                                                   , A.MIN_LINE_ITEM_END_TIME
                                                                   , A.MAX_LINE_ITEM_END_TIME
                                                                   , A.MAX_LINE_ITEM_START_TIME
                                                                   , A.WORK_ORDER_ID) LINE_SEQ
                                   , DENSE_RANK() OVER (PARTITION BY A.IRS_ATTB_11, A.IRS_ATTB_12, A.IRS_ATTB_13, A.OPERATION_ID
                                                        ORDER     BY A.MIN_OP_ITEM_START_TIME
                                                                   , A.MIN_OP_ITEM_END_TIME
                                                                   , A.MAX_OP_ITEM_END_TIME
                                                                   , A.MAX_OP_ITEM_START_TIME
                                                                   , A.WORK_ORDER_ID) OPERATION_SEQ
                              FROM   (
                                      SELECT  A.*
                                            --, DENSE_RANK() OVER (PARTITION BY A.WORK_ORDER_ID ORDER BY A.START_TIME, A.WORK_ORDER_ID) - 1 SPLIT_ORDER_SEQ
                                            , 0             AS SPLIT_ORDER_SEQ
                                            , B.IRS_ATTB_11
                                            , B.IRS_ATTB_12
                                            , B.IRS_ATTB_13
                                            , B.IRS_ATTB_14
                                            , MIN(START_TIME) OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID) MIN_LINE_ITEM_START_TIME
                                            , MAX(START_TIME) OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID) MAX_LINE_ITEM_START_TIME
                                            , MIN(END_TIME)   OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID) MIN_LINE_ITEM_END_TIME
                                            , MAX(END_TIME)   OVER (PARTITION BY A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID) MAX_LINE_ITEM_END_TIME
                                            , MIN(START_TIME) OVER (PARTITION BY B.IRS_ATTB_11, B.IRS_ATTB_12, B.IRS_ATTB_13, A.OPERATION_ID, A.ITEM_ID) MIN_OP_ITEM_START_TIME
                                            , MAX(START_TIME) OVER (PARTITION BY B.IRS_ATTB_11, B.IRS_ATTB_12, B.IRS_ATTB_13, A.OPERATION_ID, A.ITEM_ID) MAX_OP_ITEM_START_TIME
                                            , MIN(END_TIME)   OVER (PARTITION BY B.IRS_ATTB_11, B.IRS_ATTB_12, B.IRS_ATTB_13, A.OPERATION_ID, A.ITEM_ID) MIN_OP_ITEM_END_TIME
                                            , MAX(END_TIME)   OVER (PARTITION BY B.IRS_ATTB_11, B.IRS_ATTB_12, B.IRS_ATTB_13, A.OPERATION_ID, A.ITEM_ID) MAX_OP_ITEM_END_TIME                                             
                                      FROM    TH_BUF_SCM_WORK_ORDER A,
                                              TH_MST_ITEM_ROUTE_SITE B
                                      WHERE   A.MASTER_ID       = @v_master_id
                                      AND     A.PLAN_ID         = @v_plan_id
                                      AND     A.OUT_VERSION_ID  = @v_out_version_id
                                      AND     A.MASTER_ID       = B.MASTER_ID
                                      AND     A.PLAN_ID         = B.PLAN_ID
                                      AND     A.ITEM_ID         = B.ITEM_ID
                                      AND     A.SITE_ID         = B.SITE_ID
                                      AND     A.ROUTE_ID        = B.ROUTE_ID
                                      AND     A.OPERATION_ID    = B.OPERATION_ID
                                      AND     EXISTS (
                                                      SELECT 1
                                                      FROM   (
                                                              SELECT RESOURCE_ID
                                                              FROM   TH_ENG_RESOURCE
                                                              WHERE  MASTER_iD = @v_master_id
                                                              AND    PLAN_ID = @v_plan_id
                                                              AND    BATCH_TYPE = 'BATCH'
                                                              UNION  ALL
                                                              SELECT RESOURCE_ID
                                                              FROM   TH_ENG_RESOURCE A
                                                              WHERE  MASTER_iD = @v_master_id
                                                              AND    PLAN_ID = @v_plan_id
                                                              AND    MASTER_ID NOT IN ('KR_SRS')
                                                              AND    EXISTS (
                                                                              SELECT 1
                                                                              FROM   TH_MST_OP_RESOURCE B
                                                                              WHERE  A.MASTER_ID = B.MASTER_ID
                                                                              AND    A.PLAN_ID = B.PLAN_ID
                                                                              AND    A.RESOURCE_ID = B.RESOURCE_ID
                                                                              AND    B.OPERATION_ID IN ('E2000','S2000')
                                                                            )
                                                             ) X                                                                
                                                      WHERE  X.RESOURCE_ID = A.RESOURCE_ID
                                                     )                                      
                                     ) A
                             ) A
                     ) A      
              ) A
            , TH_EXP_PLANORDER      B
              LEFT  OUTER JOIN TH_MST_FIXED_PLAN E
                    ON    B.MASTER_ID = E.MASTER_ID
                    AND   B.PLAN_ID   = E.PLAN_ID
                    AND   B.PLAN_ORDER_ID = E.WORK_ORDER_ID
                    AND   E.PO_TYPE IN ('FIX','REPLAN')
            , TH_MST_RESOURCE       C
            , TH_DPP_NET_DEMAND     D
      WHERE   A.MASTER_ID         = @v_master_id
      AND     A.PLAN_ID           = @v_plan_id
      AND     A.OUT_VERSION_ID    = @v_out_version_id
      AND     A.MASTER_ID         = B.MASTER_ID
      AND     A.PLAN_ID           = B.PLAN_ID
      AND     A.WORK_ORDER_ID     = B.ORDER_ID
      AND     A.MASTER_ID         = C.MASTER_ID
      AND     A.PLAN_ID           = C.PLAN_ID
      AND     A.RESOURCE_ID       = C.RESOURCE_ID
      AND     A.MASTER_ID         = D.MASTER_ID
      AND     A.PLAN_ID           = D.PLAN_ID
      AND     B.DEMAND_ID         = D.NET_DEMAND_ID
      AND     A.SITE_ID          != 'VIRTUAL_LANE'
      
      SET @v_message = @@ROWCOUNT
      SET @n_log_count += 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DAILY_PRODUCTION_PLAN', 'INSERT', @n_log_count, null, @v_message, null 

