      ------------------------------------------------------------------------------------------------
      IF ISNULL(@v_is_wo_merge,'N') = 'Y'
      BEGIN
        UPDATE TH_EXP_DAILY_PRODUCTION_PLAN
        SET    FIX_TYPE = 'F'
        FROM   TH_EXP_DAILY_PRODUCTION_PLAN
        WHERE  INSTANCE_ID  = @v_master_id
        AND    FP_PLAN_ID   = @v_plan_id
        AND    FIX_TYPE != 'F'
        AND    DEMAND_ID IN (
                              SELECT DEMAND_ID 
                              FROM   TH_EXP_DAILY_PRODUCTION_PLAN
                              WHERE  INSTANCE_ID  = @v_master_id
                              AND    FP_PLAN_ID   = @v_plan_id
                              AND    FIX_TYPE     = 'F'
                            )

        SET @v_message = 'FIX_TYPE - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DAILY_PRODUCTION_PLAN', 'UPDATE', @n_log_count, null, @v_message, null 

      END

      BEGIN
      
        UPDATE TH_EXP_DAILY_PRODUCTION_PLAN
        SET    TH_EXP_DAILY_PRODUCTION_PLAN.PRODUCTION_TYPE = B.PRODUCTION_TYPE
        FROM   TH_EXP_DAILY_PRODUCTION_PLAN A,
               (
                SELECT WORK_ORDER_ID, 
                       MAX(ISNULL(PRODUCTION_TYPE,'MAS')) AS PRODUCTION_TYPE
                FROM   TH_MST_SCM_ORDER_STATUS
                WHERE  INSTANCE_ID = @v_master_id
                AND    FP_PLAN_ID = @v_plan_id
                GROUP BY WORK_ORDER_ID
               ) B
        WHERE  A.INSTANCE_ID = @v_master_id
        AND    A.FP_PLAN_ID = @v_plan_id
        AND    A.WORK_ORDER_ID = B.WORK_ORDER_ID

        SET @v_message = 'PRODUCTION_TYPE - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DAILY_PRODUCTION_PLAN', 'UPDATE', @n_log_count, null, @v_message, null 

      END

      -- LANE_QTY 설정
      BEGIN
        UPDATE TH_EXP_DAILY_PRODUCTION_PLAN
        SET    TH_EXP_DAILY_PRODUCTION_PLAN.LANE_QTY       = B.LANE_QTY
              ,TH_EXP_DAILY_PRODUCTION_PLAN.LANE_TACT_QTY  = B.LANE_TACT_QTY
              ,TH_EXP_DAILY_PRODUCTION_PLAN.BATCH_ORDER_ID = B.BATCH_ORDER_ID
              ,TH_EXP_DAILY_PRODUCTION_PLAN.BIN_ORDER_ID   = B.BIN_ORDER_ID
        FROM   TH_EXP_DAILY_PRODUCTION_PLAN A,
               TH_EXP_PRODUCTION_PLAN B
        WHERE  1=1
        AND    A.INSTANCE_ID    = @v_master_id
        AND    A.FP_PLAN_ID     = @v_plan_id
        AND    A.INSTANCE_ID    = B.INSTANCE_ID
        AND    A.FP_PLAN_ID     = B.FP_PLAN_ID
        AND    A.WORK_ORDER_ID  = B.WORK_ORDER_ID

        SET @v_message = 'LANE_QTY - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DAILY_PRODUCTION_PLAN', 'UPDATE', @n_log_count, null, @v_message, null 

      END

      -- OT 의 LATE 수량 표시
      BEGIN
      
        UPDATE TH_EXP_DAILY_PRODUCTION_PLAN
        SET    TH_EXP_DAILY_PRODUCTION_PLAN.PLAN_LATE_QTY = A.PLAN_QTY
        FROM   TH_EXP_DAILY_PRODUCTION_PLAN A,
               (
                SELECT A.DEMAND_ID, B.PLAN_ORDER_ID
                FROM   TH_BUF_OUT_ORDER_TRACKING A,
                       TH_EXP_PLANORDER B
                WHERE  A.MASTER_ID = B.MASTER_ID
                AND    A.PLAN_ID = B.PLAN_ID
                AND    A.ORDER_ID = B.ORDER_ID
                AND    A.LPST < A.START_TIME        -- LPST 보다 느린 START TIME 만 해당됨.
                AND    A.MASTER_ID = @v_master_id
                AND    A.PLAN_ID = @v_plan_id
                AND    A.OUT_VERSION_ID = @v_out_version_id
                GROUP  BY A.DEMAND_ID, B.PLAN_ORDER_ID
               ) B
        WHERE  A.INSTANCE_ID = @v_master_id
        AND    A.FP_PLAN_ID = @v_plan_id
        AND    A.DEMAND_ID = B.DEMAND_ID
        AND    A.WORK_ORDER_ID = B.PLAN_ORDER_ID      

        SET @v_message = 'PLAN_LATE_QTY - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DAILY_PRODUCTION_PLAN', 'UPDATE', @n_log_count, null, @v_message, null 
        
      END
      
      -- ITEM UOM UPDATE
      BEGIN
      
        UPDATE TH_EXP_PRODUCTION_PLAN
        SET    TH_EXP_PRODUCTION_PLAN.ITEM_UOM = B.ITEM_UOM
        FROM   TH_EXP_PRODUCTION_PLAN A,
               SY_SCM_ITEM_M          B
        WHERE 1=1
        AND   A.INSTANCE_ID = @v_master_id
        AND   A.FP_PLAN_ID = @v_plan_id
        AND   A.ITEM_ID = B.ITEM_ID
        AND   A.DIVISION_ID = B.DIVISION_ID
        AND   A.SITE_ID = B.SITE_ID 

        SET @v_message = 'ITEM_UOM - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN', 'UPDATE', @n_log_count, null, @v_message, null 
        
      END      

      BEGIN
      
