      BEGIN
      
        UPDATE TH_EXP_DAILY_PRODUCTION_PLAN
        SET    TH_EXP_DAILY_PRODUCTION_PLAN.ITEM_UOM = B.ITEM_UOM
        FROM   TH_EXP_DAILY_PRODUCTION_PLAN A,
               SY_SCM_ITEM_M                B
        WHERE 1=1
        AND   A.INSTANCE_ID = @v_master_id
        AND   A.FP_PLAN_ID = @v_plan_id
        AND   A.ITEM_ID = B.ITEM_ID
        AND   A.DIVISION_ID = B.DIVISION_ID
        AND   A.SITE_ID = B.SITE_ID 

        SET @v_message = 'ITEM_UOM - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DAILY_PRODUCTION_PLAN', 'UPDATE', @n_log_count, null, @v_message, null 
        
      END        
      
      -- JR/PANCAKE_QTY UPDATE
      BEGIN
      
        UPDATE TH_EXP_PRODUCTION_PLAN
        SET    TH_EXP_PRODUCTION_PLAN.ROLL_IN_QTY = (CASE WHEN UPPER(B.ITEM_UOM) = 'M'
                                                           THEN A.PLAN_IN_QTY -- Pancake
                                                           WHEN UPPER(B.ITEM_UOM) != 'M'
                                                           THEN A.PLAN_IN_QTY -- Pancake
                                                                / ISNULL(D.PATTERN_QTY,1) * (CASE WHEN (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) = 0 THEN 1
                                                                                                  ELSE (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) END )
                                                                / (CASE UPPER(B.LENGTH_UOM) WHEN 'M'  THEN 1
                                                                                            WHEN 'CM' THEN 100
                                                                                            WHEN 'MM' THEN 1000
                                                                                                      ELSE 1 END)
                                                      ELSE NULL END),
               TH_EXP_PRODUCTION_PLAN.ROLL_OUT_QTY = (CASE WHEN UPPER(B.ITEM_UOM) = 'M' 
                                                            THEN A.PLAN_QTY -- Pancake
                                                            WHEN UPPER(B.ITEM_UOM) != 'M'
                                                            THEN A.PLAN_QTY -- Pancake
                                                                / ISNULL(D.PATTERN_QTY,1) * (CASE WHEN (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) = 0 THEN 1
                                                                                                  ELSE (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) END)
                                                                / (CASE UPPER(B.LENGTH_UOM) WHEN 'M'  THEN 1
                                                                                            WHEN 'CM' THEN 100
                                                                                            WHEN 'MM' THEN 1000
                                                                                                      ELSE 1 END)
                                                       ELSE NULL END),
               TH_EXP_PRODUCTION_PLAN.JR_IN_QTY = (CASE WHEN UPPER(B.ITEM_UOM) = 'M'
                                                           THEN A.PLAN_IN_QTY / A.LANE_QTY -- Roll 
                                                           WHEN UPPER(B.ITEM_UOM) != 'M'
                                                           THEN A.PLAN_IN_QTY / A.LANE_QTY -- Roll
                                                                / ISNULL(D.PATTERN_QTY,1) * (CASE WHEN (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) = 0 THEN 1
                                                                                                  ELSE (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) END )
                                                                / (CASE UPPER(B.LENGTH_UOM) WHEN 'M'  THEN 1
                                                                                            WHEN 'CM' THEN 100
                                                                                            WHEN 'MM' THEN 1000
                                                                                                      ELSE 1 END)
                                                      ELSE NULL END),
               TH_EXP_PRODUCTION_PLAN.JR_OUT_QTY = (CASE WHEN UPPER(B.ITEM_UOM) = 'M'
                                                           THEN A.PLAN_QTY / A.LANE_QTY -- Roll 
                                                           WHEN UPPER(B.ITEM_UOM) != 'M'
                                                           THEN A.PLAN_QTY / A.LANE_QTY -- Roll
                                                                / ISNULL(D.PATTERN_QTY,1) * (CASE WHEN (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) = 0 THEN 1
                                                                                                  ELSE (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) END)
                                                                / (CASE UPPER(B.LENGTH_UOM) WHEN 'M'  THEN 1
                                                                                            WHEN 'CM' THEN 100
                                                                                            WHEN 'MM' THEN 1000
                                                                                                      ELSE 1 END)
                                                       ELSE NULL END)                                                       
        FROM TH_EXP_PRODUCTION_PLAN A,
             SY_SCM_ITEM_M          B,
             SY_SCM_ITEM_CLASS_M    C,
             SY_SCM_ITEM_LANE_M     D
        WHERE 1=1
        AND   A.INSTANCE_ID = @v_master_id
        AND   A.FP_PLAN_ID = @v_plan_id
        AND A.ITEM_ID = B.ITEM_ID
        AND A.DIVISION_ID = B.DIVISION_ID
        AND A.SITE_ID = B.SITE_ID
        AND B.ITEM_CLASS = C.CLASS_ID
        AND C.LEVEL_2_CODE = 'APC'
        AND A.DIVISION_ID = D.DIVISION_ID
        AND A.SITE_ID = D.SITE_ID
        AND A.PLANT_ID = D.PLANT_ID
        AND A.FACTORY_ID = D.FACTORY_ID
        AND A.ITEM_ID = D.ITEM_ID
        
        SET @v_message = 'ROLL_QTY - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN', 'UPDATE', @n_log_count, null, @v_message, null 
        
      END   
      
