                                                                 --THEN A.PLAN_QTY / A.LANE_QTY -- Roll
                                                                 THEN A.PLAN_IN_QTY -- Pancake
                                                                      / ISNULL(D.PATTERN_QTY,1) * (CASE WHEN (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) = 0 THEN 1
                                                                                                        ELSE (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) END )
                                                                      / (CASE UPPER(B.LENGTH_UOM) WHEN 'M'  THEN 1
                                                                                                  WHEN 'CM' THEN 100
                                                                                                  WHEN 'MM' THEN 1000
                                                                                                            ELSE 1 END)
                                                            ELSE NULL END),
               TH_EXP_DAILY_PRODUCTION_PLAN.ROLL_OUT_QTY = (CASE WHEN UPPER(B.ITEM_UOM) = 'M'
                                                                  THEN A.PLAN_QTY -- Pancake
                                                                  WHEN UPPER(B.ITEM_UOM) != 'M'
                                                                  THEN A.PLAN_QTY -- Pancake
                                                                      / ISNULL(D.PATTERN_QTY,1) * (CASE WHEN (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) = 0 THEN 1
                                                                                                        ELSE (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) END)
                                                                      / (CASE UPPER(B.LENGTH_UOM) WHEN 'M'  THEN 1
                                                                                                  WHEN 'CM' THEN 100
                                                                                                  WHEN 'MM' THEN 1000
                                                                                                            ELSE 1 END)
                                                             ELSE NULL END),
               TH_EXP_DAILY_PRODUCTION_PLAN.ROLL_LATE_QTY = (CASE WHEN UPPER(B.ITEM_UOM) = 'M'
                                                                   THEN A.PLAN_QTY -- Pancake
                                                                   WHEN UPPER(B.ITEM_UOM) != 'M'
                                                                   THEN A.PLAN_QTY -- Pancake
                                                                      / ISNULL(D.PATTERN_QTY,1) * (CASE WHEN (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) = 0 THEN 1
                                                                                                        ELSE (ISNULL(B.COATED_LENGTH,0) + ISNULL(B.UNCOATED_LENGTH, 0)) END)
                                                                      / (CASE UPPER(B.LENGTH_UOM) WHEN 'M'  THEN 1
                                                                                                  WHEN 'CM' THEN 100
                                                                                                  WHEN 'MM' THEN 1000
                                                                                                            ELSE 1 END)
                                                             ELSE NULL END) * (A.PLAN_LATE_QTY/A.PLAN_QTY),
               TH_EXP_DAILY_PRODUCTION_PLAN.JR_IN_QTY = (CASE WHEN UPPER(B.ITEM_UOM) = 'M'
                                                               THEN A.PLAN_IN_QTY / D.LANE_QTY -- Roll 
