      END               
      
      -- BATCH_QTY UPDATE
      BEGIN
      
        UPDATE TH_EXP_PRODUCTION_PLAN
        SET    TH_EXP_PRODUCTION_PLAN.BATCH_QTY = A.PLAN_IN_QTY / FLOOR(B.BATCH_LOT_SIZE)
        FROM   TH_EXP_PRODUCTION_PLAN         A,
               SY_SCM_ITEM_EQUIP_RATE_BATCH_M B
        WHERE 1=1
        AND    A.INSTANCE_ID = @v_master_id
        AND    A.FP_PLAN_ID = @v_plan_id
        AND    A.DIVISION_ID = B.DIVISION_ID
        AND    A.SITE_ID = B.SITE_ID
        AND    A.PLANT_ID = B.PLANT_ID
        AND    A.FACTORY_ID = B.FACTORY_ID
        AND    A.ITEM_ID = B.ITEM_ID
        AND    B.ACTIVE_FLAG = 'Y'
        
        SET @v_message = 'SLURRY BATCH_QTY - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN', 'UPDATE', @n_log_count, null, @v_message, null 
        
      END   

      BEGIN
      
        UPDATE TH_EXP_PRODUCTION_PLAN
        SET    TH_EXP_PRODUCTION_PLAN.BATCH_QTY = A.PLAN_QTY / B.APPLY_LOT_SIZE
        FROM   TH_EXP_PRODUCTION_PLAN A,
               TH_MST_SCM_DEMAND_LOT B
        WHERE  A.INSTANCE_ID IN (SELECT DISTINCT INSTANCE_ID FROM SY_FP_INSTANCE_FACTORY_M WHERE INSTANCE_TYPE = 'E1')
        AND    A.FP_PLAN_ID = @v_plan_id
        AND    A.FP_PLAN_ID = B.DPP_PLAN_ID
        AND    A.DIVISION_ID = B.DIVISION_ID
        AND    A.SITE_ID = B.SITE_ID
        AND    A.PLANT_ID = B.PLANT_ID
        AND    A.FACTORY_ID = B.FACTORY_ID
        AND    A.ITEM_ID = B.ITEM_ID
        
        SET @v_message = 'ROLL BATCH_QTY - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN', 'UPDATE', @n_log_count, null, @v_message, null 
        
      END        
      
      BEGIN
      
        UPDATE TH_EXP_PRODUCTION_PLAN_EQUIPMENT
        SET    TH_EXP_PRODUCTION_PLAN_EQUIPMENT.BATCH_QTY = A.PLAN_IN_QTY / FLOOR(B.BATCH_LOT_SIZE)
        FROM   TH_EXP_PRODUCTION_PLAN_EQUIPMENT A,
               SY_SCM_ITEM_EQUIP_RATE_BATCH_M   B
        WHERE  1=1
        AND    A.INSTANCE_ID = @v_master_id
        AND    A.FP_PLAN_ID = @v_plan_id
        AND    A.DIVISION_ID = B.DIVISION_ID
        AND    A.SITE_ID = B.SITE_ID
        AND    A.PLANT_ID = B.PLANT_ID
        AND    A.FACTORY_ID = B.FACTORY_ID
        AND    A.ITEM_ID = B.ITEM_ID
        AND    B.ACTIVE_FLAG = 'Y'
        
        SET @v_message = 'BATCH_QTY - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN_EQUIPMENT', 'UPDATE', @n_log_count, null, @v_message, null 
        
      END         
      
      BEGIN
      
        UPDATE TH_EXP_DAILY_PRODUCTION_PLAN
        SET    TH_EXP_DAILY_PRODUCTION_PLAN.BATCH_IN_QTY = A.PLAN_IN_QTY / FLOOR(B.BATCH_LOT_SIZE),
               TH_EXP_DAILY_PRODUCTION_PLAN.BATCH_OUT_QTY = A.PLAN_QTY / FLOOR(B.BATCH_LOT_SIZE),
               TH_EXP_DAILY_PRODUCTION_PLAN.BATCH_LATE_QTY = (CASE WHEN A.PLAN_QTY = 0 THEN 0 ELSE A.PLAN_QTY / FLOOR(B.BATCH_LOT_SIZE) * (A.PLAN_LATE_QTY/A.PLAN_QTY) END)
        FROM   TH_EXP_DAILY_PRODUCTION_PLAN   A,
               SY_SCM_ITEM_EQUIP_RATE_BATCH_M B
        WHERE  1=1
        AND    A.INSTANCE_ID = @v_master_id
        AND    A.FP_PLAN_ID = @v_plan_id
        AND    A.DIVISION_ID = B.DIVISION_ID
        AND    A.SITE_ID = B.SITE_ID
        AND    A.PLANT_ID = B.PLANT_ID
        AND    A.FACTORY_ID = B.FACTORY_ID
        AND    A.ITEM_ID = B.ITEM_ID
        AND    B.ACTIVE_FLAG = 'Y'
        AND    B.BATCH_LOT_SIZE > 0
        
        SET @v_message = 'BATCH_QTY - UPDATE : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DAILY_PRODUCTION_PLAN', 'UPDATE', @n_log_count, null, @v_message, null 
        
      END            

