-- Lot Merge
-- 20170404 ksjeon      

      BEGIN

        DELETE FROM TH_BUF_MERGE_MASTER
        WHERE  INSTANCE_ID = @v_master_id
        AND    FP_PLAN_ID  = @v_plan_id

        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_MERGE_MASTER', 'DELETE', @n_log_count, null, @v_message, null 

        insert into th_buf_merge_master
                (instance_id
                ,fp_plan_id
                ,company_id
            ,division_id
                ,site_id
                ,plant_id
                ,factory_id
                ,work_order_id
                ,merge_work_order_id
                ,item_id
                ,operation_id
                ,line_id
                ,resource_id
                ,start_time
                ,end_time
                ,plan_qty
                ,merge_plan_qty
                ,plan_in_qty
                ,merge_plan_in_qty
                ,insert_id
                ,insert_time)
        -- Merge를 위한 buf 테이블 생성
        select a.instance_id, a.fp_plan_id, a.company_id, a.division_id, a.site_id, a.plant_id, a.factory_id,
               a.work_order_id,
               substring(   min(REPLICATE(0, 3 -LEN (a.r )) + a.r + '+' + a.work_order_id ) over(partition by a.line_id, a.resource_id, a.item_id, a.start_time, a.end_time ),
                            5, 
                            len(a.work_order_id) 
                        ) 
               as merge_work_order_id,
               --a.r,
               a.item_id, a.operation_id, a.line_id, a.resource_id,
               a.start_time, a.end_time,
               a.plan_qty, 
               a.merge_plan_qty,
               a.plan_in_qty,
               a.merge_plan_in_qty
               ,@v_proc_name as insert_id, sysdatetime() as insert_time
        from   (
                select a.instance_id, a.fp_plan_id, a.company_id, a.division_id, a.site_id, a.plant_id, a.factory_id,
                       a.work_order_id,
                       --min(a.work_order_id) over(partition by a.line_id, a.item_id, a.start_time, a.end_time ) as merge_work_order_id,
                       CONVERT(VARCHAR,
                               dense_rank() over(partition by a.line_id, a.equipment_id, a.item_id, a.start_time, a.end_time
                                                 order by a.line_id, a.equipment_id, a.item_id, a.start_time, a.end_time, plan_qty desc )
                              )                   
                       as r,
                       a.item_id, a.operation_id, a.line_id, a.equipment_id as resource_id,
                       a.start_time, a.end_time,
                       a.plan_qty, 
                       sum(a.plan_qty) over(partition by a.line_id, a.equipment_id, a.item_id, a.start_time, a.end_time ) as merge_plan_qty,
                       a.plan_in_qty,
                       sum(a.plan_in_qty) over(partition by a.line_id, a.equipment_id, a.item_id, a.start_time, a.end_time ) as merge_plan_in_qty
                from   (       
                        select distinct instance_id, fp_plan_id, company_id, division_id, site_id, plant_id, factory_id,
                                        work_order_id, 
                                        item_id, operation_id, line_id, equipment_id,
                                        start_time, end_time,
                                        plan_qty, 
                                        plan_in_qty
                        from   th_exp_daily_production_plan
                        where  instance_id = @v_master_id
                        and    fp_plan_id  = @v_plan_id
                --        and line_id = 'FP_E6U02'
                --        and item_id = 'ASLSR0030A'
                --        and start_time = convert(datetime, '2017-04-04 06:00:00') 
                       ) a,
                       (
                        select * from TH_eng_resource
                        where  1=1
                        and    master_id  = @v_master_id
                        and    plan_id    = @v_plan_id
                        and    batch_type = 'BATCH'  
                       ) b
                where  a.instance_id  = b.master_id
                and    a.fp_plan_id   = b.plan_id
                and    a.equipment_id = b.resource_id
                --and a.work_order_id in (  'WK117404SX004', 'WK117404SX007' )
               ) a 

        
        SET @v_message = @@ROWCOUNT
        SET @v_table_name = 'TH_BUF_MERGE_MASTER'
        SET @n_log_count = @n_log_count + 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null
        
      END           
      
