      BEGIN
      
        ----------------------------------------------
        -- NORMAL ORDER
        UPDATE TH_EXP_PRODUCTION_PLAN
        SET    TH_EXP_PRODUCTION_PLAN.MARKET = B.MARKET
       FROM   TH_EXP_PRODUCTION_PLAN A,
               TH_DPP_NET_DEMAND      B
        WHERE  A.INSTANCE_ID    = @v_master_id
        AND    A.FP_PLAN_ID     = @v_plan_id
        AND    A.INSTANCE_ID    = B.MASTER_ID
        AND    A.FP_PLAN_ID     = B.PLAN_ID
        AND    A.DEMAND_ID      = B.NET_DEMAND_ID       -- ## MARKET 보완  ( STOCK DEMAND 도 있음 )
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN - MARKET', 'UPDATE', @n_log_count, null, @v_message, null 
      
        UPDATE TH_EXP_PRODUCTION_PLAN_EQUIPMENT
        SET    TH_EXP_PRODUCTION_PLAN_EQUIPMENT.MARKET = B.MARKET
        FROM   TH_EXP_PRODUCTION_PLAN_EQUIPMENT A,
               TH_DPP_NET_DEMAND      B
        WHERE  A.INSTANCE_ID    = @v_master_id
        AND    A.FP_PLAN_ID     = @v_plan_id
        AND    A.INSTANCE_ID    = B.MASTER_ID
        AND    A.FP_PLAN_ID     = B.PLAN_ID
        AND    A.DEMAND_ID      = B.NET_DEMAND_ID       -- ## MARKET 보완  ( STOCK DEMAND 도 있음 )
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN_EQUIPMENT - MARKET', 'UPDATE', @n_log_count, null, @v_message, null 

        UPDATE TH_EXP_DAILY_PRODUCTION_PLAN
        SET    TH_EXP_DAILY_PRODUCTION_PLAN.MARKET = B.MARKET
        FROM   TH_EXP_DAILY_PRODUCTION_PLAN A,
               TH_DPP_NET_DEMAND      B
        WHERE  A.INSTANCE_ID    = @v_master_id
        AND    A.FP_PLAN_ID     = @v_plan_id
        AND    A.INSTANCE_ID    = B.MASTER_ID
        AND    A.FP_PLAN_ID     = B.PLAN_ID
        AND    A.DEMAND_ID      = B.NET_DEMAND_ID       -- ## MARKET 보완  ( STOCK DEMAND 도 있음 )
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DAILY_PRODUCTION_PLAN - MARKET', 'UPDATE', @n_log_count, null, @v_message, null 

        ----------------------------------------------
        -- FIX ORDER
        UPDATE TH_EXP_PRODUCTION_PLAN
        SET    TH_EXP_PRODUCTION_PLAN.MARKET = B.MARKET
        FROM   TH_EXP_PRODUCTION_PLAN   A,
               TH_MST_SCM_ORDER_STATUS  B
        WHERE  A.INSTANCE_ID    = @v_master_id
        AND    A.FP_PLAN_ID     = @v_plan_id
        AND    A.INSTANCE_ID    = B.INSTANCE_ID
        AND    A.FP_PLAN_ID     = B.FP_PLAN_ID
        AND    A.WORK_ORDER_ID  = B.WORK_ORDER_ID       -- ## MARKET 보완  ( 확정 )
        AND    B.MARKET         IS NOT NULL
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN (FIX) - MARKET', 'UPDATE', @n_log_count, null, @v_message, null 
      
        UPDATE TH_EXP_PRODUCTION_PLAN_EQUIPMENT
        SET    TH_EXP_PRODUCTION_PLAN_EQUIPMENT.MARKET = B.MARKET
        FROM   TH_EXP_PRODUCTION_PLAN_EQUIPMENT A,
               TH_MST_SCM_ORDER_STATUS          B
        WHERE  A.INSTANCE_ID    = @v_master_id
        AND    A.FP_PLAN_ID     = @v_plan_id
        AND    A.INSTANCE_ID    = B.INSTANCE_ID
        AND    A.FP_PLAN_ID     = B.FP_PLAN_ID
        AND    A.WORK_ORDER_ID  = B.WORK_ORDER_ID       -- ## MARKET 보완  ( 확정 )
        AND    B.MARKET         IS NOT NULL
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN_EQUIPMENT (FIX) - MARKET', 'UPDATE', @n_log_count, null, @v_message, null 
      
        UPDATE TH_EXP_DAILY_PRODUCTION_PLAN
        SET    TH_EXP_DAILY_PRODUCTION_PLAN.MARKET = B.MARKET
        FROM   TH_EXP_DAILY_PRODUCTION_PLAN   A,
               TH_MST_SCM_ORDER_STATUS  B
        WHERE  A.INSTANCE_ID    = @v_master_id
        AND    A.FP_PLAN_ID     = @v_plan_id
        AND    A.INSTANCE_ID    = B.INSTANCE_ID
        AND    A.FP_PLAN_ID     = B.FP_PLAN_ID
        AND    A.WORK_ORDER_ID  = B.WORK_ORDER_ID       -- ## MARKET 보완  ( 확정 )
        AND    B.MARKET         IS NOT NULL
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count += 1
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PRODUCTION_PLAN (FIX) - MARKET', 'UPDATE', @n_log_count, null, @v_message, null 

      END
      
