      END           

      /*** TH_BUF_FP_PRODUCTION_PLAN_R UPDATE ***/
      BEGIN
       
        update TH_BUF_FP_PRODUCTION_PLAN_R
        set    TH_BUF_FP_PRODUCTION_PLAN_R.delete_yn           = b.delete_yn,
               TH_BUF_FP_PRODUCTION_PLAN_R.merge_work_order_id = b.merge_work_order_id,
               TH_BUF_FP_PRODUCTION_PLAN_R.new_plan_qty        = b.new_plan_qty,
               TH_BUF_FP_PRODUCTION_PLAN_R.new_plan_in_qty     = b.new_plan_in_qty,
               TH_BUF_FP_PRODUCTION_PLAN_R.change_id           = @v_proc_name
        from   TH_BUF_FP_PRODUCTION_PLAN_R a,
               (
                select a.instance_id, a.fp_plan_id, a.work_order_id, --a.resource_id, 
                       a.line_id, a.operation_id,
                       a.delete_yn, a.merge_work_order_id, a.new_plan_qty, a.new_plan_in_qty
                from   (       
                        select a.instance_id, a.fp_plan_id, a.work_order_id, --a.resource_id, 
                               a.line_id, a.operation_id,
                               case when isnull(b.merge_work_order_id, '##' ) = '##' 
                                    then ''
                                    when (a.work_order_id = isnull(b.work_order_id, '##') and a.work_order_id = isnull(b.merge_work_order_id, '##' ) ) 
                                    then 'U'
                                    else 'D'
                                    end as delete_yn, 
                               b.merge_work_order_id,     
                               b.merge_plan_qty as new_plan_qty, b.merge_plan_in_qty as new_plan_in_qty
                        from   (
                                select instance_id, 
                                       fp_plan_id, 
                                       work_order_id, 
                                       operation_id, 
                                       item_id, 
                                       line_id, 
                                       site_id, 
                                       plan_in_qty   as operation_qty, 
                                       plan_qty      as complete_qty ,
                                       start_time, 
                                       end_time
from   TH_BUF_FP_PRODUCTION_PLAN_R
                                where  instance_id      = @v_master_id
                                and    fp_plan_id       = @v_plan_id
                               ) a
                               left outer join
                               (
                                select distinct instance_id, fp_plan_id, work_order_id, merge_work_order_id, item_id, operation_id, line_id, resource_id, start_time, end_time,
                                       plan_qty, merge_plan_qty,
                                       plan_in_qty, merge_plan_in_qty
                                from   th_buf_merge_master
                                where  instance_id = @v_master_id
                                and    fp_plan_id  = @v_plan_id
                                --and work_order_id in ('wk117404sx004', 'wk117404sx007' )
                               ) b 
                               on   a.instance_id   = b.instance_id
                               and  a.fp_plan_id    = b.fp_plan_id
                               and  a.work_order_id = b.work_order_id
                       ) a
               ) b 
        where  a.instance_id    = @v_master_id
        and    a.fp_plan_id     = @v_plan_id --'KR_SRS-20170404-02'
        and    a.instance_id    = b.instance_id
        and    a.fp_plan_id     = b.fp_plan_id
        and    a.work_order_id  = b.work_order_id
        and    a.line_id        = b.line_id
        and    a.operation_id   = b.operation_id

          
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

      END



