        -- SY_FP_PRODUCTION_PLAN_EQUIPMENT_R
        BEGIN
          DELETE FROM SY_FP_PRODUCTION_PLAN_EQUIPMENT_R
          WHERE  INSTANCE_ID  = @v_master_id
          AND    FP_PLAN_ID   = @v_plan_id

          -- NORMAL WORK
          INSERT INTO SY_FP_PRODUCTION_PLAN_EQUIPMENT_R
                (
                   INSTANCE_ID
                 , FP_PLAN_ID
                 , COMPANY_ID
                 , DIVISION_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , WORK_ORDER_SPL_ID
                 , WORK_ORDER_ID
                 , BATCH_ORDER_ID
                 , BIN_ORDER_ID
                 , ORDER_TYPE
                 , SCP_TARGET_ID
                 , DEMAND_ID
                 , ITEM_ID
                 , LANE_QTY
                 , TOP_ITEM_ID
                 , TOP_WORK_ORDER_ID
                 , LINE_ID
                 , OPERATION_ID
                 , ELECTRODE_TYPE
                 , WORK_CENTER_ID
                 , EQUIPMENT_ID
                 , PLAN_DATE
                 , START_TIME
                 , END_TIME
                 , PLAN_QTY
                 , PLAN_IN_QTY
                 , ITEM_UOM
                 , ROLL_IN_QTY
                 , ROLL_OUT_QTY
                 , JR_IN_QTY
                 , JR_OUT_QTY
                 , BATCH_QTY
                 , BATCH_SUM_QTY
                 , FIX_TYPE
                 , PRODUCTION_TYPE
                 , BOM_VERSION_ID
                 , SLIT_PLANT_ID
                 , MARKET
                 , INSERT_ID
                 , INSERT_TIME
                )
          SELECT
                 A.INSTANCE_ID
               , A.FP_PLAN_ID
               , A.COMPANY_ID
               , A.DIVISION_ID
               , A.SITE_ID
               , A.PLANT_ID
               , A.FACTORY_ID
               , A.WORK_ORDER_SPL_ID
               , A.WORK_ORDER_ID
               , A.BATCH_ORDER_ID
               , A.BIN_ORDER_ID
               , A.ORDER_TYPE
               , A.SCP_TARGET_ID
               , A.DEMAND_ID
               , A.ITEM_ID
               , A.LANE_QTY
               , A.TOP_ITEM_ID
               , A.TOP_WORK_ORDER_ID
               , A.LINE_ID
               , A.OPERATION_ID
               , A.ELECTRODE_TYPE
               , A.WORK_CENTER_ID
               , A.EQUIPMENT_ID
               , A.PLAN_DATE
               , A.START_TIME
               , A.END_TIME
               , A.PLAN_QTY
               , A.PLAN_IN_QTY
               , A.ITEM_UOM
               , A.ROLL_IN_QTY
               , A.ROLL_OUT_QTY
               , A.JR_IN_QTY
               , A.JR_OUT_QTY
               , A.BATCH_QTY
               , A.BATCH_SUM_QTY
               , A.FIX_TYPE
               , A.PRODUCTION_TYPE
               , A.BOM_VERSION_ID
               , A.SLIT_PLANT_ID
               , A.MARKET
               , A.INSERT_ID
               , A.INSERT_TIME
          FROM   TH_EXP_PRODUCTION_PLAN_EQUIPMENT A
          WHERE  INSTANCE_ID  = @v_master_id
          AND    FP_PLAN_ID   = @v_plan_id
          AND    NOT EXISTS ( -- 확정 WO 제외
                              SELECT 1
                              FROM   TH_MST_SCM_FIX_WORK_SPLIT B
                              WHERE  A.INSTANCE_ID = B.MASTER_ID
                              AND    A.FP_PLAN_ID = B.PLAN_ID
                              AND    A.WORK_ORDER_ID = B.SPLIT_WORK_ORDER_ID
                            )

          SET @v_message = 'NORMAL WORK : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
          SET @n_log_count += 1
          EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'SY_FP_PRODUCTION_PLAN_EQUIPMENT_R', 'INSERT', @n_log_count, null, @v_message, null 


          -- FIX WORK

          INSERT INTO SY_FP_PRODUCTION_PLAN_EQUIPMENT_R
                (
                   INSTANCE_ID
                 , FP_PLAN_ID
                 , COMPANY_ID
                 , DIVISION_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , WORK_ORDER_SPL_ID
                 , WORK_ORDER_ID
                 , BATCH_ORDER_ID
                 , BIN_ORDER_ID
                 , ORDER_TYPE
                 , SCP_TARGET_ID
                 , DEMAND_ID
                 , ITEM_ID
                 , LANE_QTY
                 , TOP_ITEM_ID
                 , TOP_WORK_ORDER_ID
                 , LINE_ID
                 , OPERATION_ID
                 , ELECTRODE_TYPE
                 , WORK_CENTER_ID
                 , EQUIPMENT_ID
                 , PLAN_DATE
                 , START_TIME
                 , END_TIME
                 , PLAN_QTY
                 , PLAN_IN_QTY
                 , ITEM_UOM
                 , ROLL_IN_QTY
                 , ROLL_OUT_QTY
                 , JR_IN_QTY
                 , JR_OUT_QTY
                 , BATCH_QTY
                 , BATCH_SUM_QTY
                 , FIX_TYPE
                 , PRODUCTION_TYPE
                 , BOM_VERSION_ID
                 , SLIT_PLANT_ID
                 , MARKET
                 , INSERT_ID
                 , INSERT_TIME
                )
          SELECT 
                   A.INSTANCE_ID
                 , A.FP_PLAN_ID
                 , A.COMPANY_ID
                 , A.DIVISION_ID
                 , A.SITE_ID
                 , A.PLANT_ID
                 , A.FACTORY_ID
                 , A.WORK_ORDER_ID + '#' + CASE WHEN SEQ < 10 THEN '00'
                                                WHEN SEQ < 100 THEN '0'
                                                              ELSE ''
                                           END 
                                         + CONVERT(NVARCHAR, SEQ)
                    AS WORK_ORDER_SPL_ID
                 , A.WORK_ORDER_ID
                 , A.BATCH_ORDER_ID
                 , A.BIN_ORDER_ID
                 , A.ORDER_TYPE
                 , A.SCP_TARGET_ID
                 , A.DEMAND_ID
                 , A.ITEM_ID
                 , A.LANE_QTY
                 , A.TOP_ITEM_ID
                 , '' AS TOP_WORK_ORDER_ID
                 , A.LINE_ID
                 , A.OPERATION_ID
                 , A.ELECTRODE_TYPE
                 , A.WORK_CENTER_ID
                 , A.EQUIPMENT_ID
                 , A.PLAN_DATE
                 , A.START_TIME
                 , A.END_TIME
                 , A.PLAN_QTY
                 , A.PLAN_IN_QTY
                 , A.ITEM_UOM
                 , A.ROLL_IN_QTY
                 , A.ROLL_OUT_QTY
                 , A.JR_IN_QTY
                 , A.JR_OUT_QTY
                 , A.BATCH_QTY
                 , A.BATCH_SUM_QTY
                 , A.FIX_TYPE
                 , ISNULL(B.PRODUCTION_TYPE, A.PRODUCTION_TYPE) AS PRODUCTION_TYPE
                 , A.BOM_VERSION_ID
                 , A.SLIT_PLANT_ID
                 , A.MARKET
                 , A.INSERT_ID
                 , A.INSERT_TIME
          FROM   (
                  SELECT
                         A.INSTANCE_ID
                       , A.FP_PLAN_ID
                       , A.COMPANY_ID
                       , A.DIVISION_ID
                       , A.SITE_ID
                       , A.PLANT_ID
                       , A.FACTORY_ID
                       , COUNT(1) OVER (PARTITION BY B.WORK_ORDER_ID
                                        ORDER     BY A.EQUIPMENT_ID) AS SEQ
                       , B.WORK_ORDER_ID    AS WORK_ORDER_SPL_ID
                       , B.WORK_ORDER_ID
                       , A.BATCH_ORDER_ID
                       , A.BIN_ORDER_ID
                       , A.ORDER_TYPE
                       , C.DEMAND_ID            AS SCP_TARGET_ID
                       , B.DEMAND_ID
             , A.ITEM_ID
                       , A.LANE_QTY
                       , ISNULL(C.ITEM_ID, A.ITEM_ID) AS TOP_ITEM_ID
                       , NULL                         AS TOP_WORK_ORDER_ID
                       , A.LINE_ID
                       , A.OPERATION_ID
                       , A.ELECTRODE_TYPE
                       , A.WORK_CENTER_ID
                       , A.EQUIPMENT_ID
                       , MIN(A.PLAN_DATE)       AS PLAN_DATE
                       , MIN(A.START_TIME)      AS START_TIME
                       , MAX(A.END_TIME)        AS END_TIME
                       , SUM(A.PLAN_QTY)        AS PLAN_QTY
                       , SUM(A.PLAN_IN_QTY)     AS PLAN_IN_QTY
                       , A.ITEM_UOM
                       , SUM(A.ROLL_IN_QTY)     AS ROLL_IN_QTY
                       , SUM(A.ROLL_OUT_QTY)    AS ROLL_OUT_QTY
                       , SUM(A.JR_IN_QTY)       AS JR_IN_QTY
                       , SUM(A.JR_OUT_QTY)      AS JR_OUT_QTY
                       , SUM(A.BATCH_QTY)       AS BATCH_QTY
                       , SUM(A.BATCH_SUM_QTY)   AS BATCH_SUM_QTY
                       , MAX(A.FIX_TYPE)        AS FIX_TYPE
                       , MAX(A.PRODUCTION_TYPE) AS PRODUCTION_TYPE
                       , MAX(A.BOM_VERSION_ID)  AS BOM_VERSION_ID
                       , MAX(A.SLIT_PLANT_ID)   AS SLIT_PLANT_ID
                       , MAX(A.MARKET)          AS MARKET
                       , MAX(A.INSERT_ID)       AS INSERT_ID
                       , MAX(A.INSERT_TIME)     AS INSERT_TIME
                  FROM   TH_EXP_PRODUCTION_PLAN_EQUIPMENT A,
                         TH_MST_SCM_FIX_WORK_SPLIT        B,
                         TH_DPP_NET_DEMAND                C
                  WHERE  A.INSTANCE_ID    = @v_master_id
                  AND    A.FP_PLAN_ID     = @v_plan_id
                  AND    A.INSTANCE_ID    = B.MASTER_ID
                  AND    A.FP_PLAN_ID     = B.PLAN_ID
                  AND    A.WORK_ORDER_ID  = B.SPLIT_WORK_ORDER_ID
                  AND    B.MASTER_ID      = C.MASTER_ID
                  AND    B.PLAN_ID        = C.PLAN_ID
                  AND    B.DEMAND_ID      = C.NET_DEMAND_ID
                  GROUP  BY
                         A.INSTANCE_ID
                       , A.FP_PLAN_ID
                       , A.COMPANY_ID
                       , A.DIVISION_ID
                       , A.SITE_ID
                       , A.PLANT_ID
                       , A.FACTORY_ID
                       , B.WORK_ORDER_ID
                       , A.BATCH_ORDER_ID
                       , A.BIN_ORDER_ID
                       , A.ORDER_TYPE
                       , C.DEMAND_ID
                       , B.DEMAND_ID
                       , A.ITEM_ID
                       , A.LANE_QTY
                       , ISNULL(C.ITEM_ID, A.ITEM_ID)
                       , A.LINE_ID
                       , A.OPERATION_ID
                       , A.ELECTRODE_TYPE
                       , A.WORK_CENTER_ID
                       , A.EQUIPMENT_ID
                       , A.ITEM_UOM
                 ) A
                 LEFT OUTER JOIN SY_FP_MTA_OPEN_ORDER_MAP B
                      ON     A.WORK_ORDER_ID = B.WORK_ORDER_ID


          SET @v_message = 'FIX    WORK : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
          SET @n_log_count += 1
          EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'SY_FP_PRODUCTION_PLAN_EQUIPMENT_R', 'INSERT', @n_log_count, null, @v_message, null 

        END


