      /*** TH_BUF_FP_PROD_PLAN_EQUIP_R UPDATE ***/
      BEGIN
       
        update TH_BUF_FP_PROD_PLAN_EQUIP_R
        set    TH_BUF_FP_PROD_PLAN_EQUIP_R.delete_yn           = b.delete_yn,
               TH_BUF_FP_PROD_PLAN_EQUIP_R.merge_work_order_id = b.merge_work_order_id,
               TH_BUF_FP_PROD_PLAN_EQUIP_R.new_plan_qty        = b.new_plan_qty,
               TH_BUF_FP_PROD_PLAN_EQUIP_R.new_plan_in_qty     = b.new_plan_in_qty,
               TH_BUF_FP_PROD_PLAN_EQUIP_R.change_id           = @v_proc_name
