               (
                select a.instance_id, a.fp_plan_id, a.work_order_id, a.resource_id, 
                       a.delete_yn, a.merge_work_order_id, a.new_plan_qty, a.new_plan_in_qty
                from   (       
                        select a.instance_id, a.fp_plan_id, a.work_order_id, a.resource_id, 
                               case when isnull(b.merge_work_order_id, '##' ) = '##' 
                                    then ''
                                    when (a.work_order_id = isnull(b.work_order_id, '##') and a.work_order_id = isnull(b.merge_work_order_id, '##' ) ) 
                                    then 'U'
                                    else 'D'
                                    end as delete_yn, 
