        UPDATE SY_FP_PRODUCTION_PLAN_R
        SET    SY_FP_PRODUCTION_PLAN_R.MFG_WEEK           = B.WEEK
             , SY_FP_PRODUCTION_PLAN_R.DEMAND_DIVISION_ID = A.DIVISION_ID                 -- 2017.06.26 : DEMAND_DIVISION 추가
        FROM   SY_FP_PRODUCTION_PLAN_R A,
               SY_SCM_SYS_CALENDAR_M B
        WHERE  A.INSTANCE_ID  = @v_master_id
        AND    A.FP_PLAN_ID   = @v_plan_id
